/** All translations for zizhitongjian ch.165 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "資治通鑑 第165卷卷第一百六十五", literal: "Comprehensive Mirror in Aid of Governance, Volume 165, Roll 165", idiomatic: "Comprehensive Mirror in Aid of Governance, Volume 165" },
  { zh: "【梁紀二十一】　起昭陽作噩，盡閼逢閹茂，凡二年。", literal: "[Liang Records 21] From Zhaoyang Zuoe through Efeng Yanmao; two years in all.", idiomatic: "[Liang Records 21] From Zhaoyang Zuoe through Efeng Yanmao—two years in all." },
  { zh: "世祖孝元皇帝下承聖二年（", literal: "Emperor Xiaoyuan, lower scroll, second year of Chengsheng (", idiomatic: "Emperor Yuan of Liang, second year of Chengsheng (" },
  { zh: "癸酉，公元五五三年）", literal: "guiyou, 553 CE)", idiomatic: "guiyou, AD 553)" },
  { zh: "春，正月，王僧辯發建康，承製使陳霸先代鎮揚州。", literal: "In spring, the first month, Wang Senbian set out from Jiankang; by regent's order he had Chen Baxian replace him in garrisoning Yangzhou.", idiomatic: "In spring, the first month, Wang Senbian left Jiankang; acting by imperial order, he had Chen Baxian replace him as garrison commander of Yangzhou." },
  { zh: "丙子，山胡圍齊離石。", literal: "On bingzi, the Mountain Hu besieged Qi's Lishi.", idiomatic: "On bingzi, the Mountain Hu besieged Lishi in Northern Qi." },
  { zh: "戊寅，齊主討之，未至，胡已走，因巡三堆，大獵而歸。", literal: "On wuyin, the Qi ruler went to attack them; before he arrived the Hu had fled; he then toured Sandui, held a great hunt, and returned.", idiomatic: "On wuyin, Gao Yang marched against them; before he arrived the Hu had fled. He toured Sandui, held a great hunt, and returned." },
  { zh: "以吏部尚書王褒為左僕射。", literal: "Director of the Ministry of Personnel Wang Bao was made Left Vice Director of the Masters of Writing.", idiomatic: "Director of the ministry of personnel Wang Bao was made left vice director of the masters of writing." },
  { zh: "己丑，齊改鑄錢，文曰「常平五銖」。", literal: "On jichou, Qi recast coinage; the inscription read \"Changping Five Zhu.\"", idiomatic: "On jichou, Northern Qi recast coinage inscribed \"Changping Five Zhu.\"" },
  { zh: "二月，庚子，李洪雅力屈，以空雲城降陸納。", literal: "In the second month, on gengzi, Li Hongya, strength exhausted, surrendered Kongyun to Lu Na.", idiomatic: "In the second month, on gengzi, Li Hongya, exhausted, surrendered Kongyun to Lu Na." },
  { zh: "納囚洪雅，殺丁道貴。", literal: "Na imprisoned Hongya and killed Ding Daogui.", idiomatic: "Na imprisoned Hongya and killed Ding Daogui." },
  { zh: "納以沙門寶志詩識有「十八子」，以為李氏當王，甲辰，推洪雅為主，號大將軍，使乘平肩輿，列鼓吹，納帥眾數千，左右翼從。", literal: "Na, because the monk Baozhi's prophetic verse had \"eighteen sons,\" believed the Li clan would become kings; on jiachen he made Hongya leader, styled him Grand General, had him ride in a level-shouldered palanquin with music arrayed, and led several thousand men with wings left and right.", idiomatic: "Na, because the monk Baozhi's prophetic verse spoke of \"eighteen sons,\" believed the Li would rise; on jiachen he set up Hongya as leader, styled him grand general, had him ride in a level palanquin with music arrayed, and led several thousand men with wings left and right." },
  { zh: "魏太師泰去丞相、大行台，為都督中外諸軍事。", literal: "Wei Grand Preceptor Tai removed the titles Chancellor and Grand Mobile Headquarters and became Commander of All Forces Inside and Outside.", idiomatic: "Western Wei grand preceptor Yuwen Tai shed the titles chancellor and grand mobile headquarters and became commander of all forces inside and outside." },
  { zh: "王雄至東梁州，黃眾寶帥眾降。", literal: "Wang Xiong reached Eastern Liangzhou; Huang Zhongbao led his followers in surrender.", idiomatic: "Wang Xiong reached Eastern Liangzhou; Huang Zhongbao led his followers in surrender." },
  { zh: "太師泰赦之，遷其豪帥於雍州。", literal: "Grand Preceptor Tai pardoned them and moved their chieftains to Yongzhou.", idiomatic: "Yuwen Tai pardoned them and moved their chieftains to Yongzhou." },
  { zh: "齊主送柔然可汗鐵伐之父登注及兄庫提還其國。", literal: "The Qi ruler sent back to their country the father Dengzhu and elder brother Kuti of Rouran Khagan Tiefa.", idiomatic: "Gao Yang sent back to their country the father Dengzhu and elder brother Kuti of Rouran khagan Tiefa." },
  { zh: "鐵伐尋為契丹所殺，國人立登注為可汗。", literal: "Tiefa was soon killed by the Khitan; the people made Dengzhu khagan.", idiomatic: "Tiefa was soon killed by the Khitan; the people made Dengzhu khagan." },
  { zh: "登注復為其大人阿富提所殺，國人立庫提。", literal: "Dengzhu was again killed by his great man Afuti; the people made Kuti khagan.", idiomatic: "Dengzhu was again killed by his great man Afuti; the people made Kuti khagan." },
  { zh: "突厥伊利可汗卒，子科羅立，號乙息記可汗；", literal: "Tujue Khagan Yili died; his son Keluo succeeded, styled Khagan Yixiji;", idiomatic: "Tujue khagan Yili died; his son Keluo succeeded as Khagan Yixiji;" },
  { zh: "三月，遣使獻馬五萬於魏。", literal: "in the third month he sent envoys presenting fifty thousand horses to Wei.", idiomatic: "in the third month he sent envoys presenting fifty thousand horses to Western Wei." },
  { zh: "柔然別部又立阿那瓖叔父鄧叔子為可汗。", literal: "A separate division of Rouran again made Ana Gui's uncle Deng Shuzi khagan.", idiomatic: "A separate division of Rouran again made Ana Gui's uncle Deng Shuzi khagan." },
  { zh: "乙息記擊破鄧叔子於沃野北木賴山。", literal: "Yixiji defeated Deng Shuzi at Mulai Mountain north of Woye.", idiomatic: "Yixiji defeated Deng Shuzi at Mulai Mountain north of Woye." },
  { zh: "乙息記卒，捨其子攝圖而立其弟俟斤，號木桿可汗。", literal: "Yixiji died; he set aside his son Shetu and made his younger brother Houjin khagan, styled Khagan Mugan.", idiomatic: "Yixiji died; he set aside his son Shetu and made his younger brother Houjin khagan, styled Khagan Mugan." },
  { zh: "木桿狀貌奇異，性剛勇，多智略，善用兵，鄰國畏之。", literal: "Mugan was strange in face and form, fierce and brave by nature, rich in stratagem, skilled in war, and neighboring states feared him.", idiomatic: "Mugan looked strange, was fierce and brave, rich in stratagem, skilled in war, and neighboring states feared him." },
  { zh: "上聞武陵王紀東下，使方士畫版為紀像，親釘支體以厭之，又執侯景之俘以報紀。", literal: "When the emperor heard Prince Ji of Wuling was marching east, he had a geomancer paint a board into Ji's likeness and personally nailed its limbs to curse him, and also seized Hou Jing's captives to report to Ji.", idiomatic: "When the emperor heard Prince Xiao Ji of Wuling was marching east, he had a geomancer paint a board into Ji's likeness and personally nailed its limbs to curse him, and also seized Hou Jing's captives to report to Ji." },
  { zh: "初，紀之舉兵，皆太子圓照之謀也。", literal: "At first Ji's raising troops was entirely the plan of heir Yuanzhao.", idiomatic: "At first Ji's raising troops was entirely the plan of heir Yuanzhao." },
  { zh: "圓照時鎮巴東，執留使者。", literal: "Yuanzhao was then garrisoning Badong and detained envoys.", idiomatic: "Yuanzhao was then garrisoning Badong and detained envoys." },
  { zh: "啟紀云：「侯景未平，宜急進討；", literal: "He reported to Ji: \"Hou Jing is not yet pacified—you should press the attack at once;", idiomatic: "He reported to Ji: \"Hou Jing is not yet pacified—you should press the attack at once;" },
  { zh: "已聞荊鎮為景所破。", literal: "I have heard Jing province's garrison was broken by Jing.", idiomatic: "I have heard Jing province's garrison was broken by Jing." },
  { zh: "」紀信之，趣兵東下。", literal: "\" Ji believed it and hurried his army east.", idiomatic: "\" Ji believed it and hurried his army east." },
  { zh: "上甚懼，與魏書曰：「子糾，親也，請君討之。", literal: "The emperor was greatly afraid and wrote Wei: \"Zijiu is kin—please attack him.", idiomatic: "The emperor was greatly afraid and wrote Western Wei: \"Zijiu is kin—please attack him." },
  { zh: "」太師泰曰：「取蜀制梁，在茲一舉。", literal: "\" Grand Preceptor Tai said: \"To take Shu and control Liang lies in this one stroke.", idiomatic: "\" Yuwen Tai said: \"To take Shu and control Liang lies in this one stroke." },
  { zh: "」諸將鹹難之。", literal: "\" The generals all objected.", idiomatic: "\" The generals all objected." },
  { zh: "大將軍代人尉遲迥，泰之甥也，獨以為可克。", literal: "Grand General Yuchi Jiong of the Dai people, Tai's nephew by his sister, alone thought it could be overcome.", idiomatic: "Grand general Yuchi Jiong of the Dai, Yuwen Tai's nephew, alone thought it could be done." },
  { zh: "泰問以方略，迥曰：「蜀與中國隔絕百有餘年，恃其險遠，不虞我至。", literal: "Tai asked his plan; Jiong said: \"Shu and the central realm have been cut off more than a hundred years; trusting its peril and distance, they will not expect us.", idiomatic: "Tai asked his plan; Jiong said: \"Shu and the central realm have been cut off more than a hundred years; trusting its peril and distance, they will not expect us." },
  { zh: "若以鐵騎兼行襲之，無不克矣。", literal: "If iron cavalry march together in a raid, nothing will fail to be taken.\"", idiomatic: "If iron cavalry march together in a raid, nothing will fail to be taken.\"" },
  { zh: "」泰乃遣迥督開府儀同三司原珍等六軍，甲士萬二千，騎萬匹，自散關伐蜀。", literal: "\" Tai then sent Jiong to command six armies including Acting Three Excellencies Yuan Zhen, twelve thousand armored men and ten thousand horses, and invade Shu from Sanguan.", idiomatic: "\" Tai then sent Jiong to command six armies including Yuan Zhen, equal in honor to the three dukes, twelve thousand armored men and ten thousand horses, and invade Shu from Sanguan." },
  { zh: "陸納遣其將吳藏、潘烏黑、李賢明等下據車輪。", literal: "Lu Na sent his generals Wu Zang, Pan Wuhei, and Li Xianming downstream to hold Chelun.", idiomatic: "Lu Na sent his generals Wu Zang, Pan Wuhei, and Li Xianming downstream to hold Chelun." },
  { zh: "王僧辯至巴陵，宜豐侯循讓都督於僧辯，僧辯弗受。", literal: "Wang Senbian reached Baling; Marquis Xun of Yifeng yielded overall command to Senbian, but Senbian would not accept.", idiomatic: "Wang Senbian reached Baling; Marquis Xun of Yifeng yielded overall command to Senbian, but Senbian would not accept." },
  { zh: "上乃以僧辯、循為東、西都督。", literal: "The emperor then made Senbian and Xun eastern and western commanders-in-chief.", idiomatic: "The emperor then made Senbian and Xun eastern and western commanders-in-chief." },
  { zh: "夏，四月，丙申，僧辯軍於車輪。", literal: "In summer, the fourth month, on bingshen, Senbian encamped at Chelun.", idiomatic: "In summer, the fourth month, on bingshen, Senbian encamped at Chelun." },
  { zh: "吐谷渾可汗誇呂，雖通使於魏而寇抄不息，宇文泰將騎三萬逾隴，至姑臧，討之。", literal: "Tuyuhun Khagan Kualü, though sending envoys to Wei, raided without cease; Yuwen Tai led thirty thousand horse over Long to Guzang to attack him.", idiomatic: "Tuyuhun khagan Kualü, though sending envoys to Western Wei, raided without cease; Yuwen Tai led thirty thousand horse over Long to Guzang to attack him." },
  { zh: "誇呂懼，請服；", literal: "Kualü was afraid and asked to submit;", idiomatic: "Kualü was afraid and asked to submit;" },
  { zh: "既而復通使於齊。", literal: "then again sent envoys to Qi.", idiomatic: "then again sent envoys to Northern Qi." },
  { zh: "涼州刺史史寧覘知其還，襲之於赤泉，獲其僕射乞伏觸狀。", literal: "Liangzhou Inspector Shi Ning, learning of his return, raided him at Chiquan and captured his Pushe Qifu Chuzhuang.", idiomatic: "Liangzhou inspector Shi Ning, learning of his return, raided him at Chiquan and captured his pushe Qifu Chuzhuang." },
  { zh: "陸納夾岸為城，以拒王僧辯。", literal: "Lu Na built cities on both banks to resist Wang Senbian.", idiomatic: "Lu Na built cities on both banks to resist Wang Senbian." },
  { zh: "納士卒皆百戰之餘，僧辯憚之，不敢輕進，稍作連城以逼之。", literal: "Na's soldiers were all veterans of a hundred battles; Senbian feared them and did not dare advance lightly, but gradually built linked ramparts to press them.", idiomatic: "Na's soldiers were all veterans; Senbian feared them and did not advance lightly, but gradually built linked ramparts to press them." },
  { zh: "納以僧辯為怯，不設備；", literal: "Na took Senbian for timid and made no preparations;", idiomatic: "Na took Senbian for timid and made no preparations;" },
  { zh: "五月，甲子，僧辯命諸軍水陸齊進，急攻之，僧辯親執旗鼓，宜豐侯循身受矢石，拔其二城；", literal: "in the fifth month, on jiazi, Senbian ordered all armies to advance together by land and water in a fierce assault; Senbian himself bore drums and flags, Marquis Xun of Yifeng took arrows and stones on his body, and they took two of his cities;", idiomatic: "in the fifth month, on jiazi, Senbian ordered all armies to advance by land and water in a fierce assault; Senbian himself bore drums and flags, Marquis Xun of Yifeng took arrows and stones on his body, and they took two of his cities;" },
  { zh: "納眾大敗，步走，保長沙。", literal: "Na's masses were greatly defeated; he went on foot and held Changsha.", idiomatic: "Na's army was routed; he fled on foot to Changsha." },
  { zh: "乙丑，僧辯進圍之。", literal: "On yichou, Senbian advanced to besiege it.", idiomatic: "On yichou, Senbian advanced to besiege it." },
  { zh: "僧辯坐壟上視築圍壘，吳藏、李賢明帥銳卒千人開門突出，蒙楯直進，趨僧辯。", literal: "Senbian sat on the rampart watching the siege works built; Wu Zang and Li Xianming led a thousand crack troops bursting out the gate, shielded, driving straight at Senbian.", idiomatic: "Senbian sat on the rampart watching the siege works rise; Wu Zang and Li Xianming led a thousand crack troops out the gate, shields up, driving straight at Senbian." },
  { zh: "時杜崱、杜龕並侍左右，甲士衛者止百餘人，力戰拒之。", literal: "Du Ya and Du Kan were then attending at his sides; armored guards numbered only a little over a hundred, and they fought hard to repel them.", idiomatic: "Du Ya and Du Kan were at his sides; barely a hundred armored guards stood by, and they fought hard to repel them." },
  { zh: "僧辯據胡床不動，裴之橫從旁擊藏等，藏等敗退，賢明死，藏脫走入城。", literal: "Senbian sat on his folding chair unmoved; Pei Zhiheng struck Zang and the others from the side; they were defeated and withdrew; Xianming died and Zang slipped back into the city.", idiomatic: "Senbian sat on his folding chair unmoved; Pei Zhiheng struck Zang from the side; they fell back; Xianming was killed and Zang slipped back into the city." },
  { zh: "武陵王紀至巴郡，聞有魏兵，遣前梁州刺史巴西譙淹還軍救蜀。", literal: "Prince Ji of Wuling reached Ba Commandery; hearing there were Wei troops, he sent former Liangzhou Inspector Qiao Yan of Baxi back with the army to rescue Shu.", idiomatic: "Prince Xiao Ji of Wuling reached Ba Commandery; hearing Western Wei was in the field, he sent former Liangzhou inspector Qiao Yan of Baxi back with the army to rescue Shu." },
  { zh: "初，楊乾運求為梁州刺史，紀以為潼州；", literal: "At first Yang Qianyun asked to be Liangzhou Inspector and Ji made him Tongzhou Inspector;", idiomatic: "At first Yang Qianyun asked to be Liangzhou inspector and Ji made him Tongzhou inspector;" },
  { zh: "楊法琛求為黎州刺史，以為沙州：二人皆不悅。", literal: "Yang Fachen asked to be Lizhou Inspector and was made Shazhou Inspector—both were displeased.", idiomatic: "Yang Fachen asked to be Lizhou inspector and was made Shazhou inspector—both were displeased." },
  { zh: "乾運兄子略說乾運曰：「今侯景初平，宜同心戮力，保國寧民，而兄弟尋戈，此自亡之道也。", literal: "Qianyun's elder brother's son Lue urged Qianyun: \"Now Hou Jing is newly pacified—you should join hearts and strength to preserve the state and settle the people; yet brothers turn spears on one another—this is the road to self-destruction.", idiomatic: "Qianyun's nephew Lue urged Qianyun: \"Hou Jing is newly pacified—you should join hearts to preserve the state; yet brothers turn spears on one another—this is the road to ruin." },
  { zh: "夫木朽不雕，世衰難佐。", literal: "Rotten wood will not take carving; a declining age is hard to serve.", idiomatic: "Rotten wood will not take carving; a declining age is hard to serve." },
  { zh: "不如送款關中，可以功名兩全。", literal: "Better to submit to Guanzhong and win both merit and safety.\"", idiomatic: "Better to submit to Guanzhong and win both merit and safety.\"" },
  { zh: "」乾運然之，令略將二千人鎮劍閣，又遣其婿樂廣鎮安州，與法琛皆潛通於魏。", literal: "\" Qianyun agreed, had Lue lead two thousand men to hold Jiange, and also sent his son-in-law Yue Guang to hold Anzhou; both he and Fachen secretly communicated with Wei.", idiomatic: "\" Qianyun agreed, had Lue lead two thousand men to hold Jiange, and sent his son-in-law Yue Guang to hold Anzhou; both he and Fachen secretly communicated with Western Wei." },
  { zh: "魏太師泰密賜乾運鐵券，授驃騎大將軍、開府儀同三司、梁州刺史。", literal: "Wei Grand Preceptor Tai secretly gave Qianyun an iron warrant and appointed him General of Agile Cavalry, equal in honor to the three dukes with an open office, and Liangzhou Inspector.", idiomatic: "Yuwen Tai secretly gave Qianyun an iron warrant and made him general of agile cavalry, equal in honor to the three dukes with an open office, and Liangzhou inspector." },
  { zh: "尉遲迥以開府儀同三司侯呂陵始為前軍，至劍閣，略退就樂廣，翻城應始，始入據安州。", literal: "Yuchi Jiong made Hou Luling Shi, equal in honor to the three dukes, vanguard; reaching Jiange, Lue withdrew to Yue Guang, turned the city to answer Shi, and Shi entered and held Anzhou.", idiomatic: "Yuchi Jiong made Hou Luling Shi, equal in honor to the three dukes, vanguard; reaching Jiange, Lue withdrew to Yue Guang, turned the city to answer Shi, and Shi entered and held Anzhou." },
  { zh: "甲戌，迥至涪水，乾運以州降。", literal: "On jiaxu, Jiong reached Fushui; Qianyun surrendered the province.", idiomatic: "On jiaxu, Jiong reached Fushui; Qianyun surrendered the province." },
  { zh: "迥分軍守之，進襲成都。", literal: "Jiong detached troops to hold it and advanced to raid Chengdu.", idiomatic: "Jiong detached troops to hold it and advanced on Chengdu." },
  { zh: "時成都見兵不滿萬人，倉庫空竭，永豐侯摠嬰城自守，迥圍之。", literal: "At the time Chengdu's visible troops were fewer than ten thousand, storehouses were empty, Marquis Zong of Yifeng closed the city and held alone, and Jiong besieged it.", idiomatic: "Chengdu had fewer than ten thousand troops in sight, storehouses were empty, Marquis Zong of Yifeng shut the gates, and Jiong besieged it." },
  { zh: "譙淹遣江州刺史景欣、幽州刺史趙拔扈援成都，迥使原珍等擊走之。", literal: "Qiao Yan sent Jiangzhou Inspector Jing Xin and Youzhou Inspector Zhao Bahu to relieve Chengdu; Jiong sent Yuan Zhen and others to strike and drive them off.", idiomatic: "Qiao Yan sent Jiangzhou inspector Jing Xin and Youzhou inspector Zhao Bahu to relieve Chengdu; Jiong sent Yuan Zhen and others to rout them." },
  { zh: "武陵王紀至巴東，知侯景已平，乃自悔，召太子圓照責之，對曰：「侯景雖平，江陵未服。", literal: "Prince Ji of Wuling reached Badong; learning Hou Jing was pacified, he repented, summoned heir Yuanzhao and rebuked him; he replied: \"Though Hou Jing is pacified, Jiangling is not yet subdued.", idiomatic: "Prince Xiao Ji of Wuling reached Badong; learning Hou Jing was pacified, he repented, summoned heir Yuanzhao and rebuked him; he replied: \"Though Hou Jing is pacified, Jiangling is not yet subdued." },
  { zh: "」紀亦以既稱尊號，不可復為人下，欲遂東進。", literal: "\" Ji also, having already taken the supreme title, could not again be another's subject and wished to press east.", idiomatic: "\" Ji also, having already taken the supreme title, could not again be another's subject and wished to press east." },
  { zh: "將卒日夜思歸，其江州刺史王開業以為宜還救根本，更思後圖；", literal: "Officers and soldiers by day and night longed to return; his Jiangzhou Inspector Wang Kaiye held they should return to save the root and plan again later;", idiomatic: "Officers and soldiers longed to return home; his Jiangzhou inspector Wang Kaiye held they should return to save the root and plan again;" },
  { zh: "諸將皆以為然。", literal: "the generals all thought so.", idiomatic: "the generals all agreed." },
  { zh: "圓照及劉孝勝固言不可，紀從之，宣言於眾曰：「敢諫者死！", literal: "Yuanzhao and Liu Xiaosheng firmly said it could not be done; Ji followed them and proclaimed to the masses: \"Whoever dares remonstrate—death!\"", idiomatic: "Yuanzhao and Liu Xiaosheng firmly said no; Ji followed them and proclaimed: \"Whoever dares remonstrate dies!\"" },
  { zh: "」己丑，紀至西陵，軍勢甚盛，舳艫翳川。", literal: "\" On jichou, Ji reached Xiling; his army's momentum was very strong and ships darkened the river.", idiomatic: "\" On jichou, Ji reached Xiling; his army's momentum was very strong and ships darkened the river." },
  { zh: "護軍陸法和築二城於峽口兩岸，運石填江，鐵鎖斷之。", literal: "Guard-General Lu Fahe built two cities on both banks of the gorge mouth, hauled stone to fill the river, and blocked it with iron chains.", idiomatic: "Guard-general Lu Fahe built two forts on both banks of the gorge, hauled stone to fill the river, and blocked it with iron chains." },
  { zh: "帝拔任約於獄，以為晉安王司馬，使助法和拒紀，謂之曰：「汝罪不容誅，我不殺汝，本為今日！", literal: "The emperor pulled Ren Yue from prison, made him marshal of the Prince of Jin'an, and had him help Fahe resist Ji, saying to him: \"Your crime admits no execution—I did not kill you for this day!\"", idiomatic: "The emperor pulled Ren Yue from prison, made him marshal of the Prince of Jin'an, and had him help Fahe resist Ji, saying: \"Your crime admits no execution—I spared you for this day!\"" },
  { zh: "」因撤禁兵以配之，仍許妻以廬陵王續之女，使宣猛將軍劉棻與之俱。", literal: "\" He then stripped palace guard troops to assign him and also promised him the daughter of Prince Xu of Luling, sending Fierce-General Liu Fen with him.", idiomatic: "\" He stripped palace guards to assign him and promised him the daughter of Prince Xu of Luling, sending fierce-general Liu Fen with him." },
  { zh: "庚辰，巴州刺史余孝頃將兵萬人會王僧辯於長沙。", literal: "On gengchen, Bazhou Inspector Yu Xiaoqing led ten thousand men to join Wang Senbian at Changsha.", idiomatic: "On gengchen, Bazhou inspector Yu Xiaoqing led ten thousand men to join Wang Senbian at Changsha." },
  { zh: "豫章太守觀寧侯永，昏而少斷。", literal: "Administrator of Yuzhang Marquis Yong of Guanning was muddled and seldom decisive.", idiomatic: "Administrator of Yuzhang Marquis Yong of Guanning was muddled and seldom decisive." },
  { zh: "左右武蠻奴用事，軍主文重疾之。", literal: "At his side Wu Mannu held power; army commander Wen Zhong hated this.", idiomatic: "At his side Wu Mannu held power; army commander Wen Zhong hated it." },
  { zh: "永將兵討陸納，至宮亭湖，重殺蠻奴。", literal: "Yong led troops against Lu Na; reaching Gongting Lake, Zhong killed Mannu.", idiomatic: "Yong led troops against Lu Na; at Gongting Lake, Zhong killed Mannu." },
  { zh: "永軍潰，奔江陵。", literal: "Yong's army collapsed and he fled to Jiangling.", idiomatic: "Yong's army collapsed and he fled to Jiangling." },
  { zh: "重將其眾奔開建侯蕃，蕃殺之而有其眾。", literal: "Zhong led his followers to Marquis Fan of Kaijian; Fan killed him and took his troops.", idiomatic: "Zhong led his men to Marquis Fan of Kaijian; Fan killed him and took his troops." },
  { zh: "六月，壬辰，武陵王紀築連城，攻絕鐵鎖，陸法和告急相繼。", literal: "In the sixth month, on renchen, Prince Ji of Wuling built linked ramparts, attacked and severed the iron chains, and Lu Fahe's urgent reports came one after another.", idiomatic: "In the sixth month, on renchen, Prince Xiao Ji of Wuling built linked ramparts, severed the iron chains, and Lu Fahe's urgent reports came one after another." },
  { zh: "上復拔謝答仁於獄，以為步兵校尉，配兵使助法和；", literal: "The emperor again pulled Xie Daren from prison, made him infantry commandant, assigned troops to help Fahe;", idiomatic: "The emperor again pulled Xie Daren from prison, made him infantry commandant, and assigned troops to help Fahe;" },
  { zh: "又遣使送王琳，令說諭陸納。", literal: "and also sent envoys escorting Wang Lin to persuade Lu Na.", idiomatic: "and sent envoys escorting Wang Lin to persuade Lu Na." },
  { zh: "乙未，琳至長沙，僧辯使送示之，納眾悉拜且泣，使謂僧辯曰：「朝廷若赦王郎，乞聽入城。", literal: "On yiwei, Lin reached Changsha; Senbian had him shown; Na's men all bowed and wept and sent word to Senbian: \"If court pardons Lord Wang, we beg to be allowed to admit him to the city.", idiomatic: "On yiwei, Lin reached Changsha; Senbian showed him to the camp; Na's men bowed and wept and sent word to Senbian: \"If court pardons Lord Wang, let him enter the city." },
  { zh: "」僧辯不許，復送江陵。", literal: "\" Senbian would not consent and sent him back to Jiangling.", idiomatic: "\" Senbian refused and sent Lin back to Jiangling." },
  { zh: "陸法和求救不已，上欲召長沙兵，恐失陸納，乃復遣琳許其入城。", literal: "Lu Fahe's calls for rescue did not cease; the emperor wished to summon Changsha's troops but feared losing Lu Na, and so again sent Lin permitting entry to the city.", idiomatic: "Lu Fahe's calls for rescue did not cease; the emperor wished to summon Changsha's troops but feared losing Lu Na, and so again sent Lin with permission to enter." },
  { zh: "琳既入，納遂降，湘州平。", literal: "Once Lin entered, Na then surrendered and Xiangzhou was pacified.", idiomatic: "Once Lin entered, Na surrendered and Xiangzhou was pacified." },
  { zh: "上復琳官爵，使將兵西援峽口。", literal: "The emperor restored Lin's office and rank and had him lead troops west to relieve the gorge mouth.", idiomatic: "The emperor restored Lin's office and rank and had him lead troops west to relieve the gorge." },
  { zh: "甲辰，齊章武景王庫狄干卒。", literal: "On jiachen, Prince of Zhangwu Jing Kudi Gan died.", idiomatic: "On jiachen, Prince Jing Kudi Gan of Zhangwu died." },
  { zh: "武陵王紀遣將軍侯睿將眾七千，築壘與陸法和相拒。", literal: "Prince Ji of Wuling sent General Hou Rui with seven thousand men to build ramparts opposing Lu Fahe.", idiomatic: "Prince Xiao Ji of Wuling sent general Hou Rui with seven thousand men to build ramparts opposing Lu Fahe." },
  { zh: "上遣使與紀書，許其還蜀，專制一方；", literal: "The emperor sent envoys with a letter to Ji, promising he might return to Shu and rule one region exclusively;", idiomatic: "The emperor sent envoys promising Ji he might return to Shu and rule his region;" },
  { zh: "紀不從，報書如家人禮。", literal: "Ji would not obey and replied in the manner of family letters.", idiomatic: "Ji refused and replied as between kin." },
  { zh: "陸納既平，湘州諸軍相繼西上，上復與紀書曰：「吾年為一日之長，屬有平亂之功，膺此樂推，事歸當璧。", literal: "Once Lu Na was pacified, Xiangzhou's armies in succession marched west; the emperor again wrote Ji: \"I am elder by a day; I happened to have merit in pacifying rebellion and received this willing acclaim—affairs return to the jade disk.", idiomatic: "Once Lu Na was pacified, Xiangzhou's armies marched west; the emperor wrote Ji again: \"I am the elder by a day; I earned this willing acclaim in pacifying rebellion—the mandate returns to me." },
  { zh: "倘遣使乎，良所遲也。", literal: "If you would send envoys, that is what I have long awaited.", idiomatic: "Send envoys if you will—that is what I have long awaited." },
  { zh: "如曰不然，於此投筆。", literal: "If you say otherwise, lay down the brush here.", idiomatic: "If you say otherwise, lay down the brush here." },
  { zh: "友于兄弟，分形共氣，兄肥弟瘦，無復相見之期，讓棗推梨，永罷歡愉之日。", literal: "Brothers should be friendly, sharing form and breath; elder fat and younger thin—with no hope of meeting again, yielding dates and pushing pears, the days of joy ended forever.", idiomatic: "Brothers should be friendly, sharing form and breath; elder fat and younger thin—with no hope of meeting again, yielding dates and pushing pears, the days of joy ended forever." },
  { zh: "心乎愛矣，書不盡言。", literal: "The heart loves, yet writing cannot exhaust the words.\"", idiomatic: "My heart loves you, yet writing cannot exhaust the words.\"" },
  { zh: "」紀頓兵日久，頻戰不利，又聞魏寇深入，成都孤危，憂懣不知所為。", literal: "\" Ji had halted his army long; battles came often without success; he also heard Wei raiders had penetrated deep and Chengdu stood alone in peril—vexed and desperate, he knew not what to do.", idiomatic: "\" Ji had halted long; battle after battle went against him; he heard Western Wei had penetrated deep and Chengdu stood alone—vexed and desperate, he knew not what to do." },
  { zh: "乃遣其度支尚書樂奉業詣江陵求和，請依前旨還蜀。", literal: "He then sent his Director of Revenue Yue Fengye to Jiangling to seek peace and beg to return to Shu as before.", idiomatic: "He sent director of revenue Yue Fengye to Jiangling to seek peace and beg to return to Shu as promised." },
  { zh: "奉業知紀必敗，啟上曰：「蜀軍乏糧，士卒多死，危亡可待。", literal: "Fengye knew Ji must fail and reported to the emperor: \"Shu's army lacks grain; soldiers die in great numbers; ruin waits close at hand.", idiomatic: "Fengye knew Ji must fail and reported: \"Shu's army lacks grain; soldiers die in droves; ruin is near." },
  { zh: "」上遂不許其和。", literal: "\" The emperor then would not permit peace.", idiomatic: "\" The emperor then refused peace." },
  { zh: "紀以黃金一斤為餅，餅百為篋，至有百篋，銀五倍於金，錦罽、繒彩稱是，每戰，懸示將士，不以為賞。", literal: "Ji made cakes of a jin of gold, a hundred cakes per case, up to a hundred cases; silver fivefold gold; brocades and silks in proportion; each battle he hung them out to show the troops but did not use them as rewards.", idiomatic: "Ji made cakes of a jin of gold, a hundred per case, up to a hundred cases; silver five times the gold; brocades and silks to match; each battle he hung them out for the troops to see but never gave them as rewards." },
  { zh: "寧州刺史陳智祖請散之以募勇士，弗聽，智祖哭而死。", literal: "Ningzhou Inspector Chen Zhizu asked to distribute them to recruit brave men; he was not obeyed; Zhizu wept and died.", idiomatic: "Ningzhou inspector Chen Zhizu asked to distribute them to recruit brave men; Ji refused; Zhizu wept himself to death." },
  { zh: "有請事者，紀辭疾不見，由是將卒解體。", literal: "When anyone asked audience, Ji pleaded illness and would not see him; from this officers and soldiers fell apart.", idiomatic: "When anyone sought audience, Ji pleaded illness and would not see him; from this the army fell apart." },
  { zh: "秋，七月，辛未，巴東民符升等斬峽口城主公孫晃，降於王琳。", literal: "In autumn, the seventh month, on xinwei, the people of Badong, Fu Sheng and others, beheaded gorge-mouth garrison commander Gongsun Huang and surrendered to Wang Lin.", idiomatic: "In autumn, the seventh month, on xinwei, Fu Sheng and others of Badong beheaded gorge commander Gongsun Huang and surrendered to Wang Lin." },
  { zh: "謝答仁、任約進攻侯睿，破之，拔其三壘。", literal: "Xie Daren and Ren Yue advanced against Hou Rui, defeated him, and took three of his ramparts.", idiomatic: "Xie Daren and Ren Yue advanced against Hou Rui, defeated him, and took three ramparts." },
  { zh: "於是兩岸十四城俱降。", literal: "Thereupon all fourteen cities on both banks surrendered.", idiomatic: "Thereupon all fourteen cities on both banks surrendered." },
  { zh: "紀不獲退，順流東下，游擊將軍南陽樊猛追擊之，紀眾大潰，赴水死者八千餘人，猛圍而守之。", literal: "Ji could not withdraw and went downstream east; strike-general Fan Meng of Nanyang pursued; Ji's masses were greatly routed; more than eight thousand drowned; Meng surrounded and held him.", idiomatic: "Ji could not withdraw and fled downstream; strike-general Fan Meng of Nanyang pursued; Ji's army was routed; more than eight thousand drowned; Meng surrounded him." },
  { zh: "上密敕猛曰：「生還，不成功也。", literal: "The emperor secretly ordered Meng: \"Alive he returns—not success.", idiomatic: "The emperor secretly ordered Meng: \"Alive he returns—that is not success." },
  { zh: "」猛引兵至紀所，紀在舟中繞床而走，以金囊擲猛曰：「以此雇卿，送我一見七官。", literal: "\" Meng led troops to Ji's place; Ji circled his bed in the boat and threw a gold pouch at Meng, saying: \"With this I hire you—send me once to see the Seventh Officer.", idiomatic: "\" Meng reached Ji's boat; Ji circled his bed and threw a gold pouch at Meng: \"Take this—buy me one meeting with the Seventh Officer." },
  { zh: "」猛曰：「天子何由可見！", literal: "\" Meng said: \"How could the Son of Heaven be seen!", idiomatic: "\" Meng said: \"How could the Son of Heaven be seen!" },
  { zh: "殺足下，金將安之！", literal: "Kill you—where would the gold go!\"", idiomatic: "Kill you—where would the gold go!\"" },
  { zh: "」遂斬紀及其幼子圓滿。", literal: "\" He then beheaded Ji and his young son Yuanman.", idiomatic: "\" He beheaded Ji and his young son Yuanman." },
  { zh: "陸法和收太子圓照兄弟三人送江陵。", literal: "Lu Fahe took heir Yuanzhao and his three brothers and sent them to Jiangling.", idiomatic: "Lu Fahe sent heir Yuanzhao and his three brothers to Jiangling." },
  { zh: "上絕紀屬籍，賜姓饕餮氏。", literal: "The emperor struck Ji from the clan register and gave the surname Taotie.", idiomatic: "The emperor struck Ji from the clan register and gave the surname Taotie." },
  { zh: "下劉孝勝獄，已而釋之。", literal: "He put Liu Xiaosheng in prison, then released him.", idiomatic: "He imprisoned Liu Xiaosheng, then released him." },
  { zh: "上使謂江安侯圓正曰：「西軍已敗，汝父不知存亡。", literal: "The emperor had someone tell Marquis Yuanzheng of Jiang'an: \"The western army is defeated; your father's fate is unknown.", idiomatic: "The emperor had someone tell Marquis Yuanzheng of Jiang'an: \"The western army is defeated; your father's fate is unknown." },
  { zh: "」意欲使其自裁。", literal: "\" He meant to make him take his own life.", idiomatic: "\" He meant to drive him to suicide." },
  { zh: "圓正聞之號哭，稱世子不絕聲。", literal: "Yuanzheng, hearing this, wailed and called himself heir without cease.", idiomatic: "Yuanzheng wailed and called himself heir without cease." },
  { zh: "上頻使覘之，知不能死，移送廷尉獄，見圓照，曰：「兄何乃亂人骨肉，使痛酷如此！", literal: "The emperor repeatedly sent to watch; knowing he would not die, he moved him to the Minister of Justice's prison; seeing Yuanzhao, he said: \"Brother, why did you tear kin apart and bring pain this cruel!", idiomatic: "The emperor sent watchers repeatedly; knowing he would not die, he moved him to prison; seeing Yuanzhao he said: \"Brother, why tear kin apart and bring pain this cruel!" },
  { zh: "」圓照唯云「計誤」。", literal: "\" Yuanzhao only said \"a plan gone wrong.\"", idiomatic: "\" Yuanzhao only said, \"a plan gone wrong.\"" },
  { zh: "上並命絕食於獄，至嚙臂啖之，十三日而死，遠近聞而悲之。", literal: "The emperor ordered them all to fast in prison; Yuanzheng came to biting his arm and eating it; on the thirteenth day he died; near and far heard and grieved.", idiomatic: "The emperor ordered them starved in prison; Yuanzheng bit his arm and ate it; on the thirteenth day he died; near and far grieved." },
  { zh: "乙未，王僧辯還江陵。", literal: "On yiwei, Wang Senbian returned to Jiangling.", idiomatic: "On yiwei, Wang Senbian returned to Jiangling." },
  { zh: "詔諸軍各還所鎮。", literal: "An edict ordered all armies each to return to their garrisons.", idiomatic: "An edict ordered all armies back to their garrisons." },
  { zh: "魏尉遲迥圍成都五旬，永豐侯摠屢出戰，皆敗，乃請降。", literal: "Wei Yuchi Jiong besieged Chengdu fifty days; Marquis Zong of Yifeng sallied repeatedly and was always defeated, then asked to surrender.", idiomatic: "Yuchi Jiong of Western Wei besieged Chengdu fifty days; Marquis Zong of Yifeng sallied repeatedly, was always beaten, then asked to surrender." },
  { zh: "諸將欲不許，迥曰：「降之則將士全，遠人悅；", literal: "The generals wished not to permit it; Jiong said: \"If we accept surrender the officers and soldiers are preserved and distant men are pleased;", idiomatic: "The generals wished to refuse; Jiong said: \"Accept surrender and the troops are preserved and distant men pleased;" },
  { zh: "攻之則將士傷，遠人懼。", literal: "if we attack, officers and soldiers are wounded and distant men are afraid.", idiomatic: "attack and the troops are wounded and distant men afraid." },
  { zh: "」遂受之。", literal: "\" He then accepted.", idiomatic: "\" He accepted." },
  { zh: "八月，戊戌，摠與宜都王圓肅帥文武詣軍門降；", literal: "In the eighth month, on wuxu, Zong with Prince Yuansu of Yidu led civil and military officials to the army gate to surrender;", idiomatic: "In the eighth month, on wuxu, Zong with Prince Yuansu of Yidu led officials to the army gate to surrender;" },
  { zh: "迥以禮接之，與盟於益州城北。", literal: "Jiong received them with ceremony and made covenant north of Yizhou city.", idiomatic: "Jiong received them with ceremony and made covenant north of Yizhou." },
  { zh: "吏民皆復其業，唯收奴婢及儲積以賞將士，軍無私焉。", literal: "Officials and people all resumed their occupations; he only took slaves and stores to reward the soldiers—nothing private in the army.", idiomatic: "Officials and people resumed their trades; he only took slaves and stores to reward the troops—nothing private in the army." },
  { zh: "魏以摠及圓肅並為開府儀同三司，以迥為大都督益、潼等十二州諸軍事、益州刺史。", literal: "Wei made Zong and Yuansu both equal in honor to the three dukes with open offices, and made Jiong Grand Commander of the twelve provinces including Yi and Tong and Inspector of Yizhou.", idiomatic: "Western Wei made Zong and Yuansu both equal in honor to the three dukes with open offices, and made Jiong grand commander of twelve provinces including Yi and Tong and inspector of Yizhou." },
  { zh: "庚子，下詔將還建康，領軍將軍胡僧祐、太府卿黃羅漢、吏部尚書宗懍、御史中丞劉彀諫曰：「建業王氣已盡，與虜正隔一江，若有不虞，悔無及也！", literal: "On gengzi, an edict was issued that the court would return to Jiankang; Palace Guard General Hu Sengyou, Grand Steward Huang Luohan, Director of the Ministry of Personnel Zong Lin, and Imperial Censor Liu Yi remonstrated: \"Jianye's royal aura is spent; we face the barbarians across one river—if mishap comes, regret will not reach us!", idiomatic: "On gengzi an edict moved the court back to Jiankang; palace guard general Hu Sengyou, grand steward Huang Luohan, director of the ministry of personnel Zong Lin, and imperial censor Liu Yi remonstrated: \"Jianye's royal aura is spent; we face the enemy across one river—if mishap comes, regret will be too late!" },
  { zh: "且古老相承云：『荊州洲數滿百，當出天子。", literal: "Moreover an old tradition runs: 'When Jingzhou's islets number a full hundred, an emperor will arise.", idiomatic: "Moreover tradition runs: 'When Jingzhou's islets number a full hundred, an emperor will arise." },
  { zh: "』今枝江生洲，百數已滿，陛下龍飛，是其應也。", literal: "' Today islets have risen at Zhijiang and the count is full—a hundred—Your Majesty's dragon flight is its fulfillment.", idiomatic: "' Islets have risen at Zhijiang and the count is full—Your Majesty's ascent is the fulfillment." },
  { zh: "」上令朝臣議之。", literal: "\" The emperor had court ministers discuss it.", idiomatic: "\" The emperor had the court discuss it." },
  { zh: "黃門侍郎周弘正、尚書右僕射王褒曰：「今百姓未見輿駕入建康，謂是列國諸王；", literal: "Yellow Gate Attendant Zhou Hongzheng and Right Vice Director of the Masters of Writing Wang Bao said: \"Today the people have not seen the imperial carriage enter Jiankang—they take this for one prince among the feudal states;", idiomatic: "Yellow gate attendant Zhou Hongzheng and right vice director Wang Bao said: \"The people have not seen the imperial carriage enter Jiankang—they think this one prince among many;" },
  { zh: "願陛下從四海之望。", literal: "we beg Your Majesty to follow the hope of the four seas.\"", idiomatic: "we beg Your Majesty to follow the hope of all under heaven.\"" },
  { zh: "」時群臣多荊州人，皆曰：「弘正等東人也，志願東下，恐非良計。", literal: "\" At the time most ministers were men of Jingzhou; all said: \"Hongzheng and the rest are easterners—their wish is to go east; I fear this is not a good plan.", idiomatic: "\" Most ministers were men of Jingzhou; all said: \"Hongzheng and the rest are easterners—they want to go east; I fear that is no good plan." },
  { zh: "」弘正面折之曰：「東人勸東，謂非良計；", literal: "\" Hongzheng confronted them face to face: \"Easterners urging east you call no good plan;", idiomatic: "\" Hongzheng confronted them: \"Easterners urging east you call a bad plan;" },
  { zh: "君等西人欲西，豈成長策？", literal: "you westerners wishing west—how is that a lasting strategy?\"", idiomatic: "you westerners wishing west—how is that a lasting strategy?\"" },
  { zh: "」上笑。", literal: "\" The emperor laughed.", idiomatic: "\" The emperor laughed." },
  { zh: "又議於後堂，會者五百人，上問之曰：「吾欲還建康，諸卿以為如何？", literal: "Again they deliberated in the rear hall; five hundred attended; the emperor asked: \"I wish to return to Jiankang—what do you gentlemen think?\"", idiomatic: "They met again in the rear hall, five hundred strong; the emperor asked: \"I wish to return to Jiankang—what do you think?\"" },
  { zh: "」眾莫敢先對。", literal: "\" None dared answer first.", idiomatic: "\" None dared answer first." },
  { zh: "上曰：「勸吾去者左袒。", literal: "The emperor said: \"Whoever urges me to go—bare the left shoulder.\"", idiomatic: "The emperor said: \"Whoever urges me to go—bare the left shoulder.\"" },
  { zh: "」左袒者過半。", literal: "\" More than half bared the left.", idiomatic: "\" More than half bared the left." },
  { zh: "武昌太守朱買臣言於上曰：「建康舊都，山陵所在；", literal: "Administrator of Wuchang Zhu Maichen said to the emperor: \"Jiankang is the old capital; the imperial tombs are there;", idiomatic: "Administrator of Wuchang Zhu Maichen said: \"Jiankang is the old capital; the tombs are there;" },
  { zh: "荊鎮邊韁，非王者之宅。", literal: "Jing's garrison is a frontier barrier—not a king's dwelling.", idiomatic: "Jing is a frontier post—not a king's dwelling." },
  { zh: "願陛下勿疑，以致後悔。", literal: "We beg Your Majesty not to doubt and bring later regret.", idiomatic: "Do not doubt, lest you regret it later." },
  { zh: "臣家在荊州，豈不願陛下居此，但恐是臣富貴，非陛下富貴耳！", literal: "My family is in Jingzhou—would I not wish Your Majesty to stay?—but I fear it would be my wealth, not Your Majesty's!\"", idiomatic: "My family is in Jingzhou—would I not wish you to stay?—but I fear it would be my wealth, not yours!\"" },
  { zh: "」上使術士杜景豪卜之，不吉，對上曰：「未去。", literal: "\" The emperor had the technician Du Jinghao divine; it was inauspicious; answering the emperor he said: \"Do not go.", idiomatic: "\" The emperor had the diviner Du Jinghao cast; it was inauspicious; he told the emperor: \"Do not go." },
  { zh: "」退而言曰：「此兆為鬼賊所留也。", literal: "\" Withdrawing he said: \"This omen is held back by ghost rebels.", idiomatic: "\" Withdrawing he said: \"This omen is held back by ghost rebels." },
  { zh: "」上以建康凋殘，江陵全盛，意亦安之，卒從僧祐等議。", literal: "\" The emperor, because Jiankang was wasted and Jiangling flourishing, was also content in mind and finally followed Sengyou and the rest.", idiomatic: "\" Jiankang was wasted and Jiangling flourishing; the emperor was content and finally followed Sengyou and the rest." },
  { zh: "以湘州刺史王琳為衡州刺史。", literal: "Xiangzhou Inspector Wang Lin was made Hengzhou Inspector.", idiomatic: "Xiangzhou inspector Wang Lin was made Hengzhou inspector." },
  { zh: "九月，庚午，詔王僧辯還鎮建康，陳霸先復還京口。", literal: "In the ninth month, on gengwu, an edict ordered Wang Senbian back to garrison Jiankang and Chen Baxian again to Jingkou.", idiomatic: "In the ninth month, on gengwu, an edict sent Wang Senbian back to garrison Jiankang and Chen Baxian back to Jingkou." },
  { zh: "丙子，以護軍將軍陸法和為郢州刺史。", literal: "On bingzi, Guard-General Lu Fahe was made Yingzhou Inspector.", idiomatic: "On bingzi, guard-general Lu Fahe was made Yingzhou inspector." },
  { zh: "法和為政，不用刑獄，專以沙門法及西域幻術教化，部曲數千人，通謂之弟子。", literal: "Fahe governed without punishments or prisons, relying solely on monastic law and Western Regions illusion arts to teach; his household troops numbered several thousand, all called his disciples.", idiomatic: "Fahe governed without courts or prisons, teaching only by monastic law and Western illusion arts; several thousand household troops were all called his disciples." },
  { zh: "契丹寇齊邊。", literal: "The Khitan raided Qi's border.", idiomatic: "The Khitan raided the Northern Qi border." },
  { zh: "壬午，齊主北巡冀、定、幽、安，遂伐契丹。", literal: "On renwu, the Qi ruler toured north through Ji, Ding, You, and An, then attacked the Khitan.", idiomatic: "On renwu, Gao Yang toured north through Ji, Ding, You, and An, then attacked the Khitan." },
  { zh: "齊主使郭元建治水軍二萬餘人於合肥，將襲建康，納湘潭侯退，又遣將軍邢景遠、步大汗薩帥眾繼之。", literal: "The Qi ruler had Guo Yuanjian build a navy of more than twenty thousand at Hefei to strike Jiankang, welcome Marquis Tui of Xiangtan, and also sent Generals Xing Jingyuan and Budahan Sa with troops to follow.", idiomatic: "Gao Yang had Guo Yuanjian build more than twenty thousand naval men at Hefei to strike Jiankang, welcome Marquis Tui of Xiangtan, and sent generals Xing Jingyuan and Budahan Sa after with troops." },
  { zh: "陳霸先在建康聞之，白上；", literal: "Chen Baxian at Jiankang heard and reported to the emperor;", idiomatic: "Chen Baxian at Jiankang heard and reported;" },
  { zh: "上詔王僧辯鎮姑孰以御之。", literal: "the emperor ordered Wang Senbian to garrison Gushu to resist.", idiomatic: "the emperor ordered Wang Senbian to garrison Gushu to resist." },
  { zh: "冬，十月，丁酉，齊主至平州，從西道趣長塹，使司徒潘相樂帥精騎五千自東道趣青山。", literal: "In winter, the tenth month, on dingyou, the Qi ruler reached Pingzhou, went by the western road toward Changyan, and sent Minister of Education Pan Xiangyue with five thousand elite horse by the eastern road toward Qingshan.", idiomatic: "In winter, the tenth month, on dingyou, Gao Yang reached Pingzhou, took the western road toward Changyan, and sent minister of education Pan Xiangyue with five thousand elite horse by the eastern road toward Qingshan." },
  { zh: "辛丑，至白狼城。", literal: "On xinchou, he reached Bailang.", idiomatic: "On xinchou, he reached Bailang." },
  { zh: "壬寅，至昌黎城，使安德王韓軌帥精騎四千東斷契丹走路。", literal: "On renyin, he reached Changli and sent Prince of Ande Han Gui with four thousand elite horse east to cut the Khitan escape route.", idiomatic: "On renyin, he reached Changli and sent Prince Han Gui of Ande with four thousand elite horse east to cut the Khitan escape route." },
  { zh: "癸卯，至陽師水，倍道兼行，掩襲契丹。", literal: "On guimao, he reached Yangshi River, doubled his march, and surprised the Khitan.", idiomatic: "On guimao, he reached Yangshi River, doubled his march, and surprised the Khitan." },
  { zh: "齊主露髻肉袒，晝夜不息，行千餘里，逾越山嶺，為士卒先，唯食肉飲水，壯氣彌厲。", literal: "The Qi ruler bared his topknot and chest, day and night without rest, traveled more than a thousand li, crossed mountains and ridges, went before the soldiers, ate only meat and drank only water, and his fierce spirit grew ever keener.", idiomatic: "Gao Yang bared his topknot and chest, marched day and night more than a thousand li over mountains, went before the soldiers, ate only meat and drank only water, and his spirit grew ever fiercer." },
  { zh: "甲辰，與契丹遇，奮擊，大破之，虜獲十萬餘口，雜畜數百萬頭。", literal: "On jiachen he met the Khitan, struck fiercely, routed them greatly, and captured more than a hundred thousand heads and millions of mixed livestock.", idiomatic: "On jiachen he met the Khitan, struck fiercely, routed them, and took more than a hundred thousand captives and millions of livestock." },
  { zh: "潘相樂又於青山破契丹別部。", literal: "Pan Xiangyue again defeated a separate Khitan division at Qingshan.", idiomatic: "Pan Xiangyue again defeated a Khitan division at Qingshan." },
  { zh: "丁未，齊主還至營州。", literal: "On dingwei, the Qi ruler returned to Yingzhou.", idiomatic: "On dingwei, Gao Yang returned to Yingzhou." },
  { zh: "己酉，王僧辯至姑孰，遣婺州刺史侯瑱、吳郡太守張彪、吳興太守裴之橫築壘東關，以待齊師。", literal: "On jiyou, Wang Senbian reached Gushu and sent Wuzhou Inspector Hou Tian, Administrator of Wu Commandery Zhang Biao, and Administrator of Wuxing Pei Zhiheng to build ramparts at Dongguan to await the Qi army.", idiomatic: "On jiyou, Wang Senbian reached Gushu and sent Wuzhou inspector Hou Tian, Wu commandery administrator Zhang Biao, and Wuxing administrator Pei Zhiheng to fortify Dongguan against the Qi army." },
  { zh: "丁巳，齊主登碣石山，臨滄海，遂如晉陽。", literal: "On dingsi, the Qi ruler ascended Jieshi Mountain, looked on the blue sea, then went to Jinyang.", idiomatic: "On dingsi, Gao Yang ascended Jieshi Mountain, looked on the sea, then went to Jinyang." },
  { zh: "以肆州刺史斛律金為太師，乃還晉陽，拜其子豐樂為武衛大將軍，命其孫武都尚義寧公主，寵待之厚，群臣莫及。", literal: "Sizhou Inspector Hulu Jin was made Grand Preceptor; he then returned to Jinyang, invested his son Fengle as General of the Martial Guard, and gave his grandson Wudu in marriage to Princess Yining—favor thick beyond any minister.", idiomatic: "Sizhou inspector Hulu Jin was made grand preceptor; Gao Yang returned to Jinyang, made his son Fengle general of the martial guard, and married his grandson Wudu to Princess Yining—favor no minister could match." },
  { zh: "閏月，丁丑，南豫州刺史侯瑱與郭元建戰於東關，齊師大敗，溺死者萬計。", literal: "In the intercalary month, on dingchou, Southern Yuzhou Inspector Hou Tian fought Guo Yuanjian at Dongguan; the Qi army was greatly defeated and those drowned were counted by the ten thousands.", idiomatic: "In the intercalary month, on dingchou, Southern Yuzhou inspector Hou Tian fought Guo Yuanjian at Dongguan; the Qi army was routed and tens of thousands drowned." },
  { zh: "湘潭侯退復歸於鄴，王僧辯還建康。", literal: "Marquis Tui of Xiangtan returned again to Ye; Wang Senbian returned to Jiankang.", idiomatic: "Marquis Tui of Xiangtan returned to Ye; Wang Senbian returned to Jiankang." },
  { zh: "吳州刺史開建侯蕃，恃其兵強，貢獻不入，上密令其將徐佛受圖之。", literal: "Wuzhou Inspector Marquis Fan of Kaijian, trusting his army's strength, sent no tribute; the emperor secretly ordered his general Xu Foshou to plot against him.", idiomatic: "Wuzhou inspector Marquis Fan of Kaijian, trusting his strength, sent no tribute; the emperor secretly ordered Xu Foshou to plot against him." },
  { zh: "佛受使其徒詐為訟者，詣蕃，遂執之。", literal: "Foshou had his men pretend to be litigants, go to Fan, and seize him.", idiomatic: "Foshou had his men pose as litigants, go to Fan, and seize him." },
  { zh: "上以佛受為建安太守，以侍中王質為吳州刺史。", literal: "The emperor made Foshou Administrator of Jian'an and Palace Attendant Wang Zhi Inspector of Wuzhou.", idiomatic: "The emperor made Foshou administrator of Jian'an and palace attendant Wang Zhi inspector of Wuzhou." },
  { zh: "質至鄱陽，佛受置之金城，自據羅城，掌門管，繕治舟艦甲兵，質不敢與爭。", literal: "Zhi reached Poyang; Foshou put him in Jincheng, himself held Luocheng, controlled gates and passes, repaired ships and armor, and Zhi did not dare contend.", idiomatic: "Zhi reached Poyang; Foshou shut him in Jincheng, held Luocheng himself, controlled the gates, repaired ships and armor, and Zhi did not dare fight." },
  { zh: "故開建侯部曲數千人攻佛受，佛受奔南豫州，侯瑱殺之，質始得行州事。", literal: "Former Marquis Fan of Kaijian's household troops, several thousand, attacked Foshou; Foshou fled to Southern Yuzhou; Hou Tian killed him; only then could Zhi conduct provincial affairs.", idiomatic: "Several thousand of Fan's old troops attacked Foshou; Foshou fled to Southern Yuzhou; Hou Tian killed him; only then could Zhi govern the province." },
  { zh: "十一月，戊戌，以尚書右僕射王褒為左僕射，湘東太守張綰為右僕射。", literal: "In the eleventh month, on wuxu, Right Vice Director of the Masters of Writing Wang Bao was made Left Vice Director and Administrator of Xiangdong Zhang Gun Right Vice Director.", idiomatic: "In the eleventh month, on wuxu, right vice director Wang Bao was made left vice director and Xiangdong administrator Zhang Gun right vice director." },
  { zh: "己未，突厥復攻柔然，柔然舉國奔齊。", literal: "On jiwei, the Tujue again attacked Rouran; Rouran fled en masse to Qi.", idiomatic: "On jiwei, the Tujue again attacked Rouran; Rouran fled en masse to Northern Qi." },
  { zh: "癸亥，齊主自晉陽北擊突厥，迎納柔然，廢其可汗庫提，立阿那瑰子庵羅辰為可汗，置之馬邑川，給其廩餼繒帛；", literal: "On guihai, the Qi ruler from Jinyang struck north against the Tujue, welcomed Rouran, deposed Khagan Kuti, made Ana Gui's son Anluochen khagan, settled him at Mayi River, and supplied grain rations and silks;", idiomatic: "On guihai, Gao Yang from Jinyang struck north against the Tujue, welcomed Rouran, deposed Khagan Kuti, made Ana Gui's son Anluochen khagan, settled him at Mayi River, and supplied grain and silks;" },
  { zh: "親追突厥於朔州，突厥請降，許之而還。", literal: "he personally pursued the Tujue to Shuozhou; the Tujue asked to surrender and he permitted it and returned.", idiomatic: "he pursued the Tujue to Shuozhou; they asked to surrender; he permitted it and returned." },
  { zh: "自是貢獻相繼。", literal: "From this tribute followed in succession.", idiomatic: "From this tribute flowed without cease." },
  { zh: "魏尚書元烈謀殺宇文泰，事洩，泰殺之。", literal: "Wei Director of the Masters of Writing Yuan Lie plotted to kill Yuwen Tai; the matter leaked and Tai killed him.", idiomatic: "Western Wei director Yuan Lie plotted to kill Yuwen Tai; the plot leaked and Tai killed him." },
  { zh: "丙寅，上使侍中王琛使於魏。", literal: "On bingyin, the emperor sent Palace Attendant Wang Chen as envoy to Wei.", idiomatic: "On bingyin, the emperor sent palace attendant Wang Chen as envoy to Western Wei." },
  { zh: "太師泰陰有圖江陵之志，梁王察聞之，益重其貢獻。", literal: "Grand Preceptor Tai secretly harbored designs on Jiangling; Prince Cha of Liang heard and increased his tribute.", idiomatic: "Yuwen Tai secretly meant to take Jiangling; Prince Cha of Liang heard and increased his tribute." },
  { zh: "十二月，齊宿預民東方白額以城降，江西州郡皆起兵應之。", literal: "In the twelfth month, the people of Qi's Suyu, Dongfang Baie, surrendered the city; commanderies south of the river all raised troops in response.", idiomatic: "In the twelfth month, Dongfang Baie of Suyu surrendered the city; commanderies south of the Yangtze all rose in response." },
  { zh: "世祖孝元皇帝下承聖三年（", literal: "Emperor Xiaoyuan, lower scroll, third year of Chengsheng (", idiomatic: "Emperor Yuan of Liang, third year of Chengsheng (" },
  { zh: "甲戌，公元五五四年）", literal: "jiaxu, 554 CE)", idiomatic: "jiaxu, AD 554)" },
  { zh: "春，正月，癸巳，齊主自離石道討山胡，遣斛律金從顯州道，常山王演從晉州道夾攻，大破之，男子十三以上皆斬，女子及幼弱以賞軍，遂平石樓。", literal: "In spring, the first month, on guisi, the Qi ruler from the Lishi road attacked the Mountain Hu, sent Hulu Jin by the Xianzhou road and Prince of Changshan Yan by the Jinzhou road in pincers, routed them greatly, beheaded all males thirteen and above, gave women and the young as army rewards, and pacified Shilou.", idiomatic: "In spring, the first month, on guisi, Gao Yang from the Lishi road attacked the Mountain Hu, sent Hulu Jin by the Xianzhou road and Prince Yan of Changshan by the Jinzhou road in pincers, routed them, beheaded all males thirteen and above, gave women and children as army rewards, and pacified Shilou." },
  { zh: "石樓絕險，自魏世所不能至，於是遠近山胡莫不懾服。", literal: "Shilou was utterly perilous—from Wei times none could reach it; thereupon Mountain Hu near and far none but submitted in fear.", idiomatic: "Shilou was utterly perilous—since Wei times none had reached it; thereafter Mountain Hu near and far all submitted in fear." },
  { zh: "有都督戰傷，其什長路暉禮不能救，帝命刳其五藏，令九人食之，肉及穢惡皆盡。", literal: "A commander was wounded in battle; his squad chief Lu Huili could not rescue him; the emperor ordered his five viscera cut out and nine men to eat them—flesh and filth all consumed.", idiomatic: "A commander was wounded; his squad chief Lu Huili could not rescue him; the emperor ordered his entrails cut out and nine men to eat them—flesh and filth consumed to the last." },
  { zh: "自是始為威虐。", literal: "From this he began cruel oppression.", idiomatic: "From this he turned cruel." },
  { zh: "陳霸先自丹徒濟江，圍齊廣陵，秦州刺史嚴超達自秦郡進圍涇州，南豫州刺史侯瑱、吳郡太守張彪皆出石樑，為之聲援。", literal: "Chen Baxian from Dantu crossed the river and besieged Qi's Guangling; Qinzhou Inspector Yan Chaoda from Qin Commandery advanced to besiege Jingzhou; Southern Yuzhou Inspector Hou Tian and Administrator of Wu Commandery Zhang Biao all came out through Shiliang as vocal support.", idiomatic: "Chen Baxian crossed from Dantu and besieged Guangling; Qinzhou inspector Yan Chaoda from Qin Commandery besieged Jingzhou; Southern Yuzhou inspector Hou Tian and Wu commandery administrator Zhang Biao came out through Shiliang in support." },
  { zh: "辛丑，使晉陵太守杜僧明帥三千人助東方白額。", literal: "On xinchou, he sent Administrator of Jinling Du Sengming with three thousand men to help Dongfang Baie.", idiomatic: "On xinchou, he sent Jinling administrator Du Sengming with three thousand men to help Dongfang Baie." },
  { zh: "魏太師泰始作九命之典，以敘內外官爵，改流外品為九秩。", literal: "Wei Grand Preceptor Tai first made the canon of nine orders to rank inner and outer offices and ranks, changing outer-stream grades to nine ranks.", idiomatic: "Yuwen Tai first made the canon of nine orders to rank offices inside and out, changing outer-stream grades to nine ranks." },
  { zh: "魏主自元烈之死，有怨言，密謀誅太師泰；", literal: "Since Prince Yuanlie's death, the Wei emperor had nursed grievances and secretly plotted to kill Grand Preceptor Tai.", idiomatic: "Since Prince Yuanlie's death, the Wei emperor had nursed grievances and secretly plotted to kill Grand Preceptor Yuwen Tai." },
  { zh: "臨淮王育、廣平王贊垂涕切諫，不聽。", literal: "Prince Yu of Huaiyin and Prince Zan of Guangping wept and remonstrated urgently; he would not listen.", idiomatic: "Prince Yu of Huaiyin and Prince Zan of Guangping wept and pleaded urgently; he would not listen." },
  { zh: "泰諸子皆幼，兄子章武公導、中山公護皆出鎮，唯以諸婿為心膂，大都督清河公李基、義城公李暉、常山公於翼俱為武衛將軍，分掌禁兵。", literal: "All Tai's sons were young; his nephew Duke Dao of Zhangwu and Duke Hu of Zhongshan were both out on command, and he relied only on his sons-in-law as his inner guard—Grand Commander Li Ji of Qinghe, Li Hui of Yicheng, and Yu Yi of Changshan were all Martial Guard generals, each commanding part of the palace army.", idiomatic: "All Yuwen Tai's sons were young; his nephews Duke Dao of Zhangwu and Duke Hu of Zhongshan were both posted on distant commands, and he relied only on his sons-in-law as his inner guard—grand commander Li Ji of Qinghe, Li Hui of Yicheng, and Yu Yi of Changshan were all martial-guard generals, each commanding part of the palace army." },
  { zh: "基，遠之子；", literal: "Ji was Yuan's son.", idiomatic: "Ji was Li Yuan's son." },
  { zh: "暉，弼之子；", literal: "Hui was Bi's son.", idiomatic: "Hui was Li Bi's son." },
  { zh: "翼，謹之子也。", literal: "Yi was Jin's son.", idiomatic: "Yi was Yu Jin's son." },
  { zh: "由是魏主謀洩，泰廢魏主，置之雍州，立其弟齊王廓。", literal: "Thereupon the Wei emperor's plot leaked; Tai deposed the Wei emperor, placed him in Yongzhou, and enthroned his younger brother Prince Kuo of Qi.", idiomatic: "Thereupon the Wei emperor's plot leaked; Yuwen Tai deposed him, placed him in Yongzhou, and enthroned his younger brother Prince Kuo of Qi." },
  { zh: "去年號，稱元年，複姓拓跋氏。", literal: "He changed the era name, called it the first year, and restored the surname Tuoba.", idiomatic: "He changed the era name, called it the first year, and restored the surname Tuoba." },
  { zh: "九十九姓改為單者，皆復其舊。", literal: "Among the ninety-nine clans that had been changed to single-character surnames, all reverted to their old forms.", idiomatic: "Among the ninety-nine clans that had been shortened to single-character surnames, all reverted to their old forms." },
  { zh: "魏初統國三十六，大姓九十九，後多滅絕。", literal: "At the beginning of Wei rule there had been thirty-six states and ninety-nine great clans; later many were extinguished.", idiomatic: "At the beginning of Wei rule there had been thirty-six states and ninety-nine great clans; later many were extinguished." },
  { zh: "泰乃以諸將功高者為三十六國，次者為九十九姓，所將士卒亦改從其姓。", literal: "Tai then made those among the generals with the highest merit into thirty-six states and the next rank into ninety-nine clans; the soldiers they led were also made to take their surnames.", idiomatic: "Yuwen Tai then made the highest-merit generals into thirty-six states and the next rank into ninety-nine clans; the soldiers they led were also made to take their surnames." },
  { zh: "三月，丁亥，長沙王韶取巴郡。", literal: "In the third month, on dinghai, Prince Shao of Changsha took Baling.", idiomatic: "In the third month, on dinghai, Prince Shao of Changsha took Baling." },
  { zh: "甲辰，以王僧辯為太尉、車騎大將軍。", literal: "On jiachen, Wang Senbian was made Grand Commandant and Grand General of Chariots and Cavalry.", idiomatic: "On jiachen, Wang Senbian was made grand commandant and grand general of chariots and cavalry." },
  { zh: "丁未，齊將王球攻宿預，杜僧明出擊，大破之，球歸彭城。", literal: "On dingwei, Qi general Wang Qiu attacked Suyu; Du Sengming sortied and routed him, and Qiu returned to Pengcheng.", idiomatic: "On dingwei, Qi general Wang Qiu attacked Suyu; Du Sengming sortied and routed him, and Qiu returned to Pengcheng." },
  { zh: "郢州刺史陸法和上啟自稱司徒，上怪之。", literal: "Yingzhou Inspector Lu Fahe memorialized the throne claiming for himself the title of Minister of Works; the emperor was astonished.", idiomatic: "Yingzhou inspector Lu Fahe memorialized the throne claiming for himself the title of minister of works; the emperor was astonished." },
  { zh: "王褒曰：「法和既有道術，容或先知。", literal: "Wang Bao said, \"Fahe has occult arts—perhaps he foreknew in advance.", idiomatic: "Wang Bao said, \"Fahe has occult arts—perhaps he foreknew in advance." },
  { zh: "」戊申，上就拜法和為司徒。", literal: "\" On wushen, the emperor at once invested Fahe as Minister of Works.", idiomatic: "\" On wushen, the emperor at once invested Fahe as minister of works." },
  { zh: "己酉，魏侍中宇文仁恕來聘。", literal: "On jiyou, Wei's attendant-in-ordinary Yuwen Renshu came on a mission of friendship.", idiomatic: "On jiyou, Western Wei's attendant-in-ordinary Yuwen Renshu came on a mission of friendship." },
  { zh: "會齊使者亦至江陵，帝接仁恕不及齊使，仁恕歸，以告太師泰。", literal: "Just then Qi's envoy also reached Jiangling; the emperor received Renshu less warmly than the Qi envoy. Renshu returned and reported this to Grand Preceptor Tai.", idiomatic: "Just then Qi's envoy also reached Jiangling; the emperor received Renshu less warmly than the Qi envoy. Renshu returned and reported this to Grand Preceptor Yuwen Tai." },
  { zh: "帝又請據舊圖定疆境，辭頗不遜，泰曰：「古人有言，『天之所棄，誰能興之』，其蕭繹之謂乎！", literal: "The emperor also asked to fix the borders according to the old maps, his language quite insolent. Tai said, \"The ancients had a saying: 'Heaven's castaway—who can raise him?' Does that not fit Xiao Yi!", idiomatic: "The emperor also asked to fix the borders according to the old maps, his language quite insolent. Yuwen Tai said, \"The ancients had a saying: 'Heaven's castaway—who can raise him?' Does that not fit Xiao Yi!" },
  { zh: "」荊州刺史長孫儉屢陳攻取之策，泰征儉入朝，問以經略，覆命還鎮，密為之備。", literal: "\" Jingzhou Inspector Zhangsun Jian repeatedly submitted plans to attack and take him; Tai summoned Jian to court, questioned him on strategy, sent him back to his post, and secretly made preparations.", idiomatic: "\" Jingzhou inspector Zhangsun Jian repeatedly submitted plans to attack and take him; Yuwen Tai summoned Jian to court, questioned him on strategy, sent him back to his post, and secretly made preparations." },
  { zh: "馬伯符密使告帝，帝弗之信。", literal: "Ma Bofu secretly sent word to the emperor; the emperor did not believe him.", idiomatic: "Ma Bofu secretly sent word to the emperor; the emperor did not believe him." },
  { zh: "柔然可汗庵羅辰叛齊，齊主自將出擊，大破之，庵羅辰父子北走。", literal: "Rouran Khan Anluochen rebelled against Qi; the Qi ruler personally took the field, routed them, and Anluochen father and son fled north.", idiomatic: "Rouran khan Anluochen rebelled against Qi; the Qi ruler personally took the field, routed them, and Anluochen father and son fled north." },
  { zh: "太保安定王賀拔仁獻馬不甚駿，齊主怒，拔其發，免為庶人，輸晉陽負炭。", literal: "Grand Marshal Prince He of Anding presented horses not very swift; the Qi ruler was angry, tore out his hair, degraded him to commoner, and sent him to Jinyang to haul charcoal.", idiomatic: "Grand marshal Prince He of Anding presented horses not very swift; the Qi ruler was angry, tore out his hair, degraded him to commoner, and sent him to Jinyang to haul charcoal." },
  { zh: "齊中書令魏收撰《魏書》，頗用愛憎為褒貶，每謂人曰：「何物小子，敢與魏收作色！", literal: "Qi Secretariat Director Wei Shou compiled the Wei History, often using personal likes and dislikes for praise and blame, and would tell people, \"What sort of whelp dares bandy words with Wei Shou!", idiomatic: "Qi secretariat director Wei Shou compiled the Wei History, often letting personal likes and dislikes govern praise and blame, and would tell people, \"What sort of whelp dares bandy words with Wei Shou!" },
  { zh: "舉之則使升天，按之則使入地！", literal: "Lift him and he ascends to heaven; press him and he sinks to earth!", idiomatic: "Lift him and he ascends to heaven; press him and he sinks to earth!" },
  { zh: "」既成，中書舍人盧潛奏：「收誣罔一代，罪當誅！", literal: "\" When it was finished, Secretariat Gentleman Lu Qian memorialized, \"Shou has slandered a whole age—his crime deserves death!", idiomatic: "\" When it was finished, secretariat gentleman Lu Qian memorialized, \"Shou has slandered a whole age—his crime deserves death!" },
  { zh: "」尚書左丞盧斐、頓丘李庶皆言《魏史》不直。", literal: "\" Left Assistant Director Lu Fei of the Secretariat and Dunqiu Li Shu both said the Wei History was not straight.", idiomatic: "\" Left assistant director Lu Fei of the secretariat and Li Shu of Dunqiu both said the Wei History was not straight." },
  { zh: "收啟齊主云：「臣既結怨強宗，將為刺客所殺。", literal: "Shou reported to the Qi ruler, \"Your servant has made enemies of powerful clans and will be killed by assassins.", idiomatic: "Shou reported to the Qi ruler, \"Your servant has made enemies of powerful clans and will be killed by assassins." },
  { zh: "」帝怒，於是斐、庶及尚書郎中王松年皆坐謗史，鞭二百，配甲坊。", literal: "\" The emperor was angry; thereupon Fei, Shu, and Secretariat Cadet Wang Songnian were all punished for slandering the history—two hundred lashes and assignment to the armor workshop.", idiomatic: "\" The emperor was angry; thereupon Fei, Shu, and secretariat cadet Wang Songnian were all punished for slandering the history—two hundred lashes and assignment to the armor workshop." },
  { zh: "斐、庶死於獄中，潛亦坐繫獄。", literal: "Fei and Shu died in prison; Qian was also imprisoned.", idiomatic: "Fei and Shu died in prison; Qian was also imprisoned." },
  { zh: "然時人終不服，謂之「穢史」。", literal: "Yet people to the end were not convinced and called it the \"Foul History.\"", idiomatic: "Yet people to the end were not convinced and called it the \"Foul History.\"" },
  { zh: "潛，度世之曾孫；", literal: "Qian was Dushi's great-grandson.", idiomatic: "Qian was Lu Dushi's great-grandson." },
  { zh: "斐，同之子；", literal: "Fei was Tong's son.", idiomatic: "Fei was Lu Tong's son." },
  { zh: "松年，遵業之子也。", literal: "Songnian was Zunyue's son.", idiomatic: "Songnian was Wang Zunyue's son." },
  { zh: "夏，四月，柔然寇齊肆州，齊主自晉陽討之，至恆州，柔然散走。", literal: "In summer, the fourth month, Rouran raided Qi's Sizhou; the Qi ruler marched from Jinyang to attack them, reached Hengzhou, and Rouran scattered and fled.", idiomatic: "In summer, the fourth month, Rouran raided Qi's Sizhou; the Qi ruler marched from Jinyang to attack them, reached Hengzhou, and Rouran scattered and fled." },
  { zh: "帝以二千餘騎為殿，宿黃瓜堆。", literal: "The emperor took more than two thousand horsemen as rearguard and encamped at Huangguadui.", idiomatic: "The emperor took more than two thousand horsemen as rearguard and encamped at Huangguadui." },
  { zh: "柔然別部數萬騎奄至，帝安臥，平明乃起，神色自若，指畫形勢，縱兵奮擊。", literal: "Several tens of thousands of horsemen of a separate Rouran division suddenly arrived; the emperor lay at ease, rose only at dawn, looked perfectly calm, pointed out the situation, and loosed his troops in fierce attack.", idiomatic: "Several tens of thousands of horsemen of a separate Rouran division suddenly arrived; the emperor lay at ease, rose only at dawn, looked perfectly calm, pointed out the situation, and loosed his troops in fierce attack." },
  { zh: "柔然披靡，因潰圍而出。", literal: "Rouran broke and scattered; he then burst through the encirclement and came out.", idiomatic: "Rouran broke and scattered; he then burst through the encirclement and came out." },
  { zh: "柔然走，追擊之，伏屍二十餘里，獲庵羅辰妻子，虜三萬餘口，令都督善無高阿那肱帥騎數千塞其走路。", literal: "Rouran fled; he pursued them; corpses lay more than twenty li; he captured Anluochen's wife and children and took more than thirty thousand captives, and ordered Commander Gao Nachin of Shanwu to lead several thousand horsemen and block their escape route.", idiomatic: "Rouran fled; he pursued them; corpses lay more than twenty li; he captured Anluochen's wife and children and took more than thirty thousand captives, and ordered commander Gao Nachin of Shanwu to lead several thousand horsemen and block their escape route." },
  { zh: "時柔然軍猶盛，阿那肱以兵少，請益，帝更減其半。", literal: "At that time the Rouran army was still strong; Nachin, with few troops, asked for reinforcements, and the emperor further cut his force in half.", idiomatic: "At that time the Rouran army was still strong; Nachin, with few troops, asked for reinforcements, and the emperor further cut his force in half." },
  { zh: "阿那肱奮擊，大破之。", literal: "Nachin struck fiercely and routed them.", idiomatic: "Nachin struck fiercely and routed them." },
  { zh: "庵羅辰超越巖谷，僅以身免。", literal: "Anluochen crossed ravines and cliffs and barely escaped with his life.", idiomatic: "Anluochen crossed ravines and cliffs and barely escaped with his life." },
  { zh: "丙寅，上使散騎常侍庾信等聘於魏。", literal: "On bingyin, the emperor sent Supernumerary Cavalier Attendant Yu Xin and others on a mission of friendship to Wei.", idiomatic: "On bingyin, the emperor sent supernumerary cavalier attendant Yu Xin and others on a mission of friendship to Western Wei." },
  { zh: "癸酉，以陳霸先為司空。", literal: "On guiyou, Chen Baxian was made Minister of Works.", idiomatic: "On guiyou, Chen Baxian was made minister of works." },
  { zh: "丁未，齊主復自擊柔然，大破之。", literal: "On dingwei, the Qi ruler again personally attacked Rouran and routed them.", idiomatic: "On dingwei, the Qi ruler again personally attacked Rouran and routed them." },
  { zh: "庚戌，魏太師泰鴆殺廢帝。", literal: "On gengxu, Wei Grand Preceptor Tai poisoned the deposed emperor.", idiomatic: "On gengxu, Western Wei grand preceptor Yuwen Tai poisoned the deposed emperor." },
  { zh: "五月，魏直州人樂熾、洋州人黃國等作亂，開府儀同三司高平田弘、河南賀若敦討之，不克。", literal: "In the fifth month, the people of Zhizhou, Yue Chi, and Yangzhou, Huang Guo and others, rose in rebellion; Palace Gate Commander of the First Rank Tian Hong of Gaoping and Henan's He Ruo Dun campaigned against them but could not overcome them.", idiomatic: "In the fifth month, the people of Zhizhou, Yue Chi, and Yangzhou, Huang Guo and others, rose in rebellion; palace gate commander of the first rank Tian Hong of Gaoping and Henan's He Ruo Dun campaigned against them but could not overcome them." },
  { zh: "太師泰命車騎大將軍李遷哲與敦共討熾等，平之。", literal: "Grand Preceptor Tai ordered Grand General of Chariots and Cavalry Li Qianzhe to campaign with Dun against Chi and the rest and pacified them.", idiomatic: "Grand preceptor Yuwen Tai ordered grand general of chariots and cavalry Li Qianzhe to campaign with Dun against Chi and the rest and pacified them." },
  { zh: "仍與敦南出，徇地至巴州，巴州刺史牟安民降之，巴、濮之民皆附於魏。", literal: "He then marched south with Dun, subdued territory as far as Bazhou; Bazhou Inspector Mou Anmin surrendered to him, and the people of Ba and Pu all submitted to Wei.", idiomatic: "He then marched south with Dun, subdued territory as far as Bazhou; Bazhou inspector Mou Anmin surrendered to him, and the people of Ba and Pu all submitted to Western Wei." },
  { zh: "蠻酋向五子王等陷白帝，遷哲擊之，五子王等遁去，遷哲追擊，破之。", literal: "The Man chieftain Xiang Wuziwang and others took Baidi; Qianzhe attacked them, Wuziwang and the rest fled, and Qianzhe pursued and defeated them.", idiomatic: "The Man chieftain Xiang Wuziwang and others took Baidi; Qianzhe attacked them, Wuziwang and the rest fled, and Qianzhe pursued and defeated them." },
  { zh: "泰以遷哲為信州刺史，鎮白帝。", literal: "Tai made Qianzhe Inspector of Xinzhou and garrisoned Baidi.", idiomatic: "Yuwen Tai made Qianzhe inspector of Xinzhou and garrisoned Baidi." },
  { zh: "信州先無儲蓄，遷哲與軍士共采葛根為糧，時有異味，輒分嘗之，軍士感悅。", literal: "Xinzhou at first had no stores; Qianzhe and the soldiers together gathered kudzu root for food; whenever there was a strange taste he would share and taste it, and the soldiers were moved and pleased.", idiomatic: "Xinzhou at first had no stores; Qianzhe and the soldiers together gathered kudzu root for food; whenever there was a strange taste he would share and taste it, and the soldiers were moved and pleased." },
  { zh: "屢擊叛蠻，破之，群蠻懾服，皆送糧餼，遣子弟入質。", literal: "He repeatedly struck rebellious Man and defeated them; the Man tribes were awed and submitted, all sending grain and provisions and sending sons as hostages.", idiomatic: "He repeatedly struck rebellious Man and defeated them; the Man tribes were awed and submitted, all sending grain and provisions and sending sons as hostages." },
  { zh: "由是州境安息，軍儲亦贍。", literal: "Thereupon the commandery was tranquil and military stores were ample.", idiomatic: "Thereupon the commandery was tranquil and military stores were ample." },
  { zh: "柔然乙旃達官寇魏廣武，柱國李弼追擊，破之。", literal: "Rouran Yizhan official raided Wei's Guangwu; pillar of state Li Bi pursued and defeated them.", idiomatic: "Rouran Yizhan official raided Western Wei's Guangwu; pillar of state Li Bi pursued and defeated them." },
  { zh: "廣州刺史曲江侯勃，自以非上所授，內不自安，上亦疑之。", literal: "Guangzhou Inspector Marquis Bo of Qujiang, because his post had not been granted by the emperor, was inwardly ill at ease, and the emperor also suspected him.", idiomatic: "Guangzhou inspector Marquis Bo of Qujiang, because his post had not been granted by the emperor, was inwardly ill at ease, and the emperor also suspected him." },
  { zh: "勃啟求入朝；", literal: "Bo memorialized asking to come to court.", idiomatic: "Bo memorialized asking to come to court." },
  { zh: "五月，乙巳，上以王琳為廣州刺史，勃為晉州刺史。", literal: "In the fifth month, on yisi, the emperor made Wang Lin Inspector of Guangzhou and Bo Inspector of Jinzhou.", idiomatic: "In the fifth month, on yisi, the emperor made Wang Lin inspector of Guangzhou and Bo inspector of Jinzhou." },
  { zh: "上以琳部眾強盛，又得眾心，故欲遠之。", literal: "The emperor, because Lin's following was strong and he had won the people's hearts, therefore wished to send him far away.", idiomatic: "The emperor, because Lin's following was strong and he had won the people's hearts, therefore wished to send him far away." },
  { zh: "琳與主書廣漢李膺厚善，私謂膺曰：「琳，小人也，蒙官拔擢至此。", literal: "Lin was on close terms with Chief Clerk Li Ying of Guanghan; privately he told Ying, \"Lin is a petty man whom official grace raised to this height.", idiomatic: "Lin was on close terms with chief clerk Li Ying of Guanghan; privately he told Ying, \"Lin is a petty man whom official grace raised to this height." },
  { zh: "今天下未定，遷琳嶺南，如有不虞，安得琳力！", literal: "The realm is not yet settled; to transfer Lin to Lingnan—if there is misfortune, how can I bring Lin's strength to bear!", idiomatic: "The realm is not yet settled; to transfer Lin to Lingnan—if there is misfortune, how can I bring Lin's strength to bear!" },
  { zh: "竊揆官意不過疑琳，琳分望有限，豈與官爭為帝乎！", literal: "I privately gauge that official intent is no more than suspicion of Lin; Lin's ambitions are limited—how could I contend with official for the throne!", idiomatic: "I privately gauge that official intent is no more than suspicion of Lin; Lin's ambitions are limited—how could I contend with official for the throne!" },
  { zh: "何不以琳為雍州刺史，鎮武寧，琳自放兵作田，為國御捍。", literal: "Why not make Lin Inspector of Yongzhou and garrison Wuning? Lin himself would release troops to farm the fields and defend the state on its behalf.", idiomatic: "Why not make Lin inspector of Yongzhou and garrison Wuning? Lin himself would release troops to farm the fields and defend the state on its behalf." },
  { zh: "」膺然其言而弗敢啟。", literal: "\" Ying thought the words right but did not dare report them.", idiomatic: "\" Ying thought the words right but did not dare report them." },
  { zh: "散騎郎新野庾季才言於上曰：「去年八月丙申，月犯心中星，今月丙戌，赤氣干北斗。", literal: "Cavalier Attendant Yu Jicai of Xinye told the emperor, \"Last year, eighth month, bingchen, the moon violated the Heart star; this month, bingxu, red vapor crossed the Northern Dipper.", idiomatic: "Cavalier attendant Yu Jicai of Xinye told the emperor, \"Last year, eighth month, bingchen, the moon violated the Heart star; this month, bingxu, red vapor crossed the Northern Dipper." },
  { zh: "心為天王，丙主楚分，臣恐建子之月有大兵入江陵。", literal: "The Heart is the Heavenly King; bing governs the Chu quarter—I fear in the month of jianzi great armies will enter Jiangling.", idiomatic: "The Heart is the Heavenly King; bing governs the Chu quarter—I fear in the month of jianzi great armies will enter Jiangling." },
  { zh: "陛下宜留重臣鎮江陵，整旆還都以避其患。", literal: "Your Majesty should leave weighty ministers to garrison Jiangling, array banners, and return to the capital to avoid the calamity.", idiomatic: "Your Majesty should leave weighty ministers to garrison Jiangling, array banners, and return to the capital to avoid the calamity." },
  { zh: "假令魏虜侵蹙，止失荊、湘，在於社稷，猶得無慮。", literal: "Even if Wei invaders press hard, you would lose only Jing and Xiang; for the altars of state, there would still be no worry.", idiomatic: "Even if Wei invaders press hard, you would lose only Jing and Xiang; for the altars of state, there would still be no worry." },
  { zh: "」上亦曉天文，知楚有災，歎曰：「禍福在天，避之何益！", literal: "\" The emperor also understood astronomy, knew Chu had a disaster, and sighed, \"Fortune and misfortune lie with Heaven—what good is fleeing!", idiomatic: "\" The emperor also understood astronomy, knew Chu had a disaster, and sighed, \"Fortune and misfortune lie with Heaven—what good is fleeing!" },
  { zh: "六月，壬午，齊步大汗薩將兵四萬趣涇州，王僧辯使侯瑱、張彪自石樑引兵助嚴超達拒之，瑱、彪遲留不進。", literal: "In the sixth month, on renwu, Qi's Bu Da Hansa led forty thousand troops toward Jingzhou; Wang Senbian sent Hou Chen and Zhang Biao from Shiliang to lead troops to help Yan Chaoda resist them; Chen and Biao lingered and did not advance.", idiomatic: "In the sixth month, on renwu, Qi's Bu Da Hansa led forty thousand troops toward Jingzhou; Wang Senbian sent Hou Chen and Zhang Biao from Shiliang to lead troops to help Yan Chaoda resist them; Chen and Biao lingered and did not advance." },
  { zh: "將軍尹令思將萬餘人謀襲盱眙。", literal: "General Yin Lingsi was about to lead more than ten thousand men in a surprise attack on Xuyi.", idiomatic: "General Yin Lingsi was about to lead more than ten thousand men in a surprise attack on Xuyi." },
  { zh: "齊冀州刺史段韶將兵討東方白額於宿預，廣陵、涇州皆來告急，諸將患之。", literal: "Qi Jizhou Inspector Duan Shao led troops to suppress the eastern white-foreheaded rebels at Suyu; Guangling and Jingzhou both sent urgent reports, and the generals were troubled.", idiomatic: "Qi Jizhou inspector Duan Shao led troops to suppress the eastern white-foreheaded rebels at Suyu; Guangling and Jingzhou both sent urgent reports, and the generals were troubled." },
  { zh: "韶曰：「梁氏喪亂，國無定主，人懷去就，強者從之。", literal: "Shao said, \"The Liang house is in turmoil; the state has no fixed lord; men think of leaving or staying and follow the strong.", idiomatic: "Shao said, \"The Liang house is in turmoil; the state has no fixed lord; men think of leaving or staying and follow the strong." },
  { zh: "霸先等外托同德，內有離心，諸君不足憂，吾揣之熟矣！", literal: "Baxian and the rest outwardly claim common purpose but inwardly are divided—you gentlemen need not worry; I have gauged them thoroughly!", idiomatic: "Baxian and the rest outwardly claim common purpose but inwardly are divided—you gentlemen need not worry; I have gauged them thoroughly!" },
  { zh: "」乃留儀同三司敬顯攜等圍宿預，自引兵倍道趣涇州，塗出盱眙。", literal: "\" He then left Palace Attendant of the Third Rank Jing Xianqi and others to besiege Suyu, himself led troops by forced marches toward Jingzhou, and the route passed Xuyi.", idiomatic: "\" He then left palace attendant of the third rank Jing Xianqi and others to besiege Suyu, himself led troops by forced marches toward Jingzhou, and the route passed Xuyi." },
  { zh: "令思不意齊兵猝至，望風退走。", literal: "Lingsi did not expect Qi troops to arrive so suddenly; at sight of them he retreated.", idiomatic: "Lingsi did not expect Qi troops to arrive so suddenly; at sight of them he retreated." },
  { zh: "韶進擊超達，破之，回趣廣陵，陳霸先解圍走。", literal: "Shao advanced, attacked Chaoda, defeated him, then turned toward Guangling; Chen Baxian lifted the siege and withdrew.", idiomatic: "Shao advanced, attacked Chaoda, defeated him, then turned toward Guangling; Chen Baxian lifted the siege and withdrew." },
  { zh: "杜僧明還丹徒，侯瑱、張彪還秦郡。", literal: "Du Sengming returned to Dantu; Hou Chen and Zhang Biao returned to Qin commandery.", idiomatic: "Du Sengming returned to Dantu; Hou Chen and Zhang Biao returned to Qin commandery." },
  { zh: "吳明徹圍海西，鎮將中山郎基固守，削木為箭，剪紙為羽。", literal: "Wu Mingche besieged Haixi; the garrison commander Lang Ji of Zhongshan held firm, carving wood for arrow shafts and cutting paper for fletching.", idiomatic: "Wu Mingche besieged Haixi; the garrison commander Lang Ji of Zhongshan held firm, carving wood for arrow shafts and cutting paper for fletching." },
  { zh: "圍之十旬，卒不能克而還。", literal: "After besieging for ten ten-day periods, in the end he could not take it and withdrew.", idiomatic: "After besieging for ten ten-day periods, in the end he could not take it and withdrew." },
  { zh: "柔然帥餘眾東徙，且欲南寇，齊主帥輕騎邀之於金川。", literal: "The Rouran commander led the remainder east and also intended to raid south; the Qi ruler led light cavalry to intercept them at Jinchuan.", idiomatic: "The Rouran commander led the remainder east and also intended to raid south; the Qi ruler led light cavalry to intercept them at Jinchuan." },
  { zh: "柔然聞之，遠遁，營州刺史靈丘王峻設伏擊之，獲其名王數十人。", literal: "Hearing this, Rouran fled far away; Yingzhou Inspector Prince Jun of Lingqiu laid an ambush, struck them, and captured several tens of their named kings.", idiomatic: "Hearing this, Rouran fled far away; Yingzhou inspector Prince Jun of Lingqiu laid an ambush, struck them, and captured several tens of their named kings." },
  { zh: "鄧至羌簷桁失國，奔魏，太師泰使秦州刺史宇文導將兵納之。", literal: "The Dengzhi Qiang chieftain Zhanheng lost his state and fled to Wei; Grand Preceptor Tai sent Qinzhou Inspector Yuwen Dao to lead troops and install him.", idiomatic: "The Dengzhi Qiang chieftain Zhanheng lost his state and fled to Western Wei; grand preceptor Yuwen Tai sent Qinzhou inspector Yuwen Dao to lead troops and install him." },
  { zh: "齊段韶還至宿預，使辯士說東方白額，白額開門請盟，因執而斬之。", literal: "Qi's Duan Shao returned to Suyu, sent an eloquent man to persuade the eastern white-foreheaded rebel; the rebel opened the gate and asked for alliance, whereupon Shao seized and beheaded him.", idiomatic: "Qi's Duan Shao returned to Suyu, sent an eloquent man to persuade the eastern white-foreheaded rebel; the rebel opened the gate and asked for alliance, whereupon Shao seized and beheaded him." },
  { zh: "秋，七月，庚戌，齊主還鄴。", literal: "In autumn, the seventh month, on gengxu, the Qi ruler returned to Ye.", idiomatic: "In autumn, the seventh month, on gengxu, the Qi ruler returned to Ye." },
  { zh: "魏太師泰西巡，至原州。", literal: "Wei Grand Preceptor Tai toured west, reaching Yuanzhou.", idiomatic: "Western Wei grand preceptor Yuwen Tai toured west, reaching Yuanzhou." },
  { zh: "八月，千辰，齊以司州牧清河王岳為太保，司空尉粲為司徒，太子太師侯莫陳相為司空，尚書令平陽王淹錄尚書事，常山王演為尚書令，中書令上黨王渙為左僕射。", literal: "In the eighth month, on gengchen, Qi made Minister of State Prince Yue of Qinghe Grand Tutor, Minister of Works Wei Can Minister of Works, Grand Tutor of the Heir Hou Mochen Xiang Minister of Works, Director of the Secretariat Prince Yan of Pingyang overseer of secretariat affairs, Prince Yan of Changshan Director of the Secretariat, and Secretariat Director Prince Huan of Shangdang Left Vice Director.", idiomatic: "In the eighth month, on gengchen, Qi made minister of state Prince Yue of Qinghe grand tutor, minister of works Wei Can minister of works, grand tutor of the heir Hou Mochen Xiang minister of works, director of the secretariat Prince Yan of Pingyang overseer of secretariat affairs, Prince Yan of Changshan director of the secretariat, and secretariat director Prince Huan of Shangdang left vice director." },
  { zh: "乙亥，齊儀同三司元旭坐事賜死。", literal: "On yihai, Qi's Palace Attendant of the Third Rank Yuan Xu was sentenced to death by imperial gift.", idiomatic: "On yihai, Qi's palace attendant of the third rank Yuan Xu was sentenced to death by imperial gift." },
  { zh: "丁丑，齊主如晉陽。", literal: "On dingchou, the Qi ruler went to Jinyang.", idiomatic: "On dingchou, the Qi ruler went to Jinyang." },
  { zh: "齊主之未為魏相也，太保、錄尚書事平原王高隆之常侮之，及將受禪，隆之復以為不可，齊主由是銜之。", literal: "Before the Qi ruler had been Wei chancellor, Grand Tutor and Overseer of Secretariat Affairs Gao Longzhi of Pingyuan had often insulted him; when he was about to receive the abdication, Longzhi again held it impossible, and the Qi ruler therefore harbored resentment.", idiomatic: "Before the Qi ruler had been Wei chancellor, grand tutor and overseer of secretariat affairs Gao Longzhi of Pingyuan had often insulted him; when he was about to receive the abdication, Longzhi again held it impossible, and the Qi ruler therefore harbored resentment." },
  { zh: "崔季舒譖「隆之每見訴訟者輒加哀矜之意，以示非己能裁。", literal: "Cui Jishu slandered him: \"Whenever Longzhi sees litigants he adds words of pity, to show it is not his own power to judge.", idiomatic: "Cui Jishu slandered him: \"Whenever Longzhi sees litigants he adds words of pity, to show it is not his own power to judge." },
  { zh: "」帝禁之尚書省。", literal: "\" The emperor confined him in the Secretariat.", idiomatic: "\" The emperor confined him in the secretariat." },
  { zh: "隆之嘗與元旭飲，謂旭曰：「與王交，當生死不相負。", literal: "Longzhi had once drunk with Yuan Xu and told Xu, \"In friendship with you, I would live and die without failing you.", idiomatic: "Longzhi had once drunk with Yuan Xu and told Xu, \"In friendship with you, I would live and die without failing you." },
  { zh: "」人有密言之者，帝由是發怒，令壯士築百餘拳而捨之。", literal: "\" Someone reported this secretly; the emperor therefore grew angry, had stalwarts strike him more than a hundred blows with clubs, and let him go.", idiomatic: "\" Someone reported this secretly; the emperor therefore grew angry, had stalwarts strike him more than a hundred blows with clubs, and let him go." },
  { zh: "辛巳，卒於路。", literal: "On xinsi, he died on the road.", idiomatic: "On xinsi, he died on the road." },
  { zh: "久之，帝追忿隆之，執其子慧登等二十人於前，帝以鞭叩鞍，一時頭絕，並投屍漳水；", literal: "After a long while the emperor pursued his wrath against Longzhi, seized his sons Huideng and twenty others before him, beat the saddle with a whip, and at one stroke all their heads fell; he cast the corpses into the Zhang waters as well.", idiomatic: "After a long while the emperor pursued his wrath against Longzhi, seized his sons Huideng and twenty others before him, beat the saddle with a whip, and at one stroke all their heads fell; he cast the corpses into the Zhang as well." },
  { zh: "又發隆之塚，出其屍，斬截骸骨焚之，棄於漳水。", literal: "He also opened Longzhi's tomb, took out the corpse, cut and burned the bones, and cast them into the Zhang.", idiomatic: "He also opened Longzhi's tomb, took out the corpse, cut and burned the bones, and cast them into the Zhang." },
  { zh: "齊主使常山王演、上黨王渙、清河王岳、平原王段韶帥眾於洛陽西南築伐惡城、新城、嚴城、河南城。", literal: "The Qi ruler ordered Prince Yan of Changshan, Prince Huan of Shangdang, Prince Yue of Qinghe, and Prince Shao of Pingyuan to lead the masses southwest of Luoyang and build Fae City, New City, Yan City, and Henan City.", idiomatic: "The Qi ruler ordered Prince Yan of Changshan, Prince Huan of Shangdang, Prince Yue of Qinghe, and Prince Shao of Pingyuan to lead the masses southwest of Luoyang and build Fae City, New City, Yan City, and Henan City." },
  { zh: "九月，齊主巡四城，欲以致魏師，魏師不出，乃如晉陽。", literal: "In the ninth month, the Qi ruler inspected the four cities, wishing to lure Wei armies out; Wei armies did not come out, and he then went to Jinyang.", idiomatic: "In the ninth month, the Qi ruler inspected the four cities, wishing to lure Wei armies out; Wei armies did not come out, and he then went to Jinyang." },
  { zh: "魏宇文泰命侍中崔猷開回車路以通漢中。", literal: "Wei Yuwen Tai ordered Attendant-in-Ordinary Cui You to open the Huiche Road to connect with Hanzhong.", idiomatic: "Western Wei's Yuwen Tai ordered attendant-in-ordinary Cui You to open the Huiche Road to connect with Hanzhong." },
  { zh: "帝好玄談，辛卯，於龍光殿講《老子》。", literal: "The emperor loved arcane discourse; on xinmao, at the Hall of Dragon Glory he lectured on the Laozi.", idiomatic: "The emperor loved arcane discourse; on xinmao, at the Hall of Dragon Glory he lectured on the Laozi." },
  { zh: "曲江侯勃遷居始興，王琳使副將孫瑒先行據番禺。", literal: "Marquis Bo of Qujiang moved to reside at Shixing; Wang Lin sent his deputy Sun Chang ahead to seize Panyu first.", idiomatic: "Marquis Bo of Qujiang moved to reside at Shixing; Wang Lin sent his deputy Sun Chang ahead to seize Panyu first." },
  { zh: "乙巳，魏遣柱國常山公於謹、中山公宇文護、大將軍楊忠將兵五萬入寇。", literal: "On yisi, Wei sent pillar of state Duke Jin of Changshan, Duke Hu of Zhongshan Yuwen Hu, and Grand General Yang Zhong to lead fifty thousand troops in invasion.", idiomatic: "On yisi, Western Wei sent pillar of state Duke Jin of Changshan, Duke Hu of Zhongshan Yuwen Hu, and grand general Yang Zhong to lead fifty thousand troops in invasion." },
  { zh: "冬，十月，壬戌，發長安。", literal: "In winter, the tenth month, on renxu, they set out from Chang'an.", idiomatic: "In winter, the tenth month, on renxu, they set out from Chang'an." },
  { zh: "長孫儉問謹曰：「為蕭繹之計，將如何？", literal: "Zhangsun Jian asked Jin, \"For Xiao Yi's plan, what will he do?", idiomatic: "Zhangsun Jian asked Yu Jin, \"For Xiao Yi's plan, what will he do?" },
  { zh: "」謹曰：「耀兵漢、沔，席捲度江，直據丹楊，上策也；", literal: "\" Jin said, \"Display troops on the Han and Mian, sweep across the river, and seize Danyang directly—that is the upper stratagem.", idiomatic: "\" Yu Jin said, \"Display troops on the Han and Mian, sweep across the river, and seize Danyang directly—that is the upper stratagem." },
  { zh: "移郭內居民退保子城，峻其陴堞，以待援軍，中策也；", literal: "Move residents within the outer wall back to hold the inner citadel, heighten its battlements, and await relief—that is the middle stratagem.", idiomatic: "Move residents within the outer wall back to hold the inner citadel, heighten its battlements, and await relief—that is the middle stratagem." },
  { zh: "若難於移動，據守羅郭，下策也。", literal: "If moving is difficult, hold the outer ring of walls—that is the lower stratagem.", idiomatic: "If moving is difficult, hold the outer ring of walls—that is the lower stratagem." },
  { zh: "」儉曰：「揣繹定出何策？", literal: "\" Jian said, \"Which stratagem do you gauge Yi will use?", idiomatic: "\" Jian said, \"Which stratagem do you gauge Yi will use?" },
  { zh: "」謹曰：「下策。", literal: "\" Jin said, \"The lower stratagem.", idiomatic: "\" Yu Jin said, \"The lower stratagem." },
  { zh: "」儉曰：「何故？", literal: "\" Jian said, \"For what reason?", idiomatic: "\" Jian said, \"For what reason?" },
  { zh: "」謹曰：「蕭氏保據江南，綿歷數紀，屬中原多故，未遑外略；", literal: "\" Jin said, \"The Xiao house has held the south of the Yangtze for generations spanning several reigns; the central plains have had many troubles and had no leisure for outward campaigns.", idiomatic: "\" Yu Jin said, \"The Xiao house has held the south of the Yangtze for generations spanning several reigns; the central plains have had many troubles and had no leisure for outward campaigns." },
  { zh: "又以我有齊氏之患，必謂力不能分。", literal: "Moreover, because we have the trouble of Qi, he will certainly think our strength cannot be divided.", idiomatic: "Moreover, because we have the trouble of Qi, he will certainly think our strength cannot be divided." },
  { zh: "且繹懦而無謀，多疑少斷。", literal: "Moreover, Yi is timid and without strategy, suspicious and slow to decide.", idiomatic: "Moreover, Yi is timid and without strategy, suspicious and slow to decide." },
  { zh: "愚民難與慮始，皆戀邑居，所以知其用下策也。", literal: "Common people are hard to take into counsel at the start; all cling to their towns and homes—therefore I know he will use the lower stratagem.", idiomatic: "Common people are hard to take into counsel at the start; all cling to their towns and homes—therefore I know he will use the lower stratagem." },
  { zh: "癸亥，武寧太守宗均告魏兵且至，帝召公卿議之。", literal: "On guihai, Wuning Administrator Zong Jun reported that Wei troops were about to arrive; the emperor summoned the high ministers to discuss it.", idiomatic: "On guihai, Wuning administrator Zong Jun reported that Wei troops were about to arrive; the emperor summoned the high ministers to discuss it." },
  { zh: "領軍胡僧祐、太府卿黃羅漢曰：「二國通好，未有嫌隙，必應不爾。", literal: "Commander of the Guards Hu Sengyou and Grand Steward Huang Luohan said, \"The two states are on friendly terms and have no cause for suspicion—surely it cannot be so.", idiomatic: "Commander of the guards Hu Sengyou and grand steward Huang Luohan said, \"The two states are on friendly terms and have no cause for suspicion—surely it cannot be so." },
  { zh: "」侍中王琛曰：「臣揣宇文容色，必無此理。", literal: "\" Attendant-in-Ordinary Wang Chen said, \"Your servant gauges Yuwen's bearing—there can be no such reason.", idiomatic: "\" Attendant-in-ordinary Wang Chen said, \"Your servant gauges Yuwen's bearing—there can be no such reason." },
  { zh: "」乃復使琛使魏。", literal: "\" He then again sent Chen as envoy to Wei.", idiomatic: "\" He then again sent Chen as envoy to Western Wei." },
  { zh: "丙寅，於謹至樊、鄧，梁王察帥眾會之。", literal: "On bingyin, Yu Jin reached Fan and Deng; Prince Cha of Liang led his forces to join him.", idiomatic: "On bingyin, Yu Jin reached Fan and Deng; Prince Xiao Cha of Liang led his forces to join him." },
  { zh: "丁卯，帝停講，內外戒嚴。", literal: "On dingmao, the emperor halted his lectures; inside and outside were placed on alert.", idiomatic: "On dingmao, the emperor halted his lectures; inside and outside were placed on alert." },
  { zh: "王琛至石梵，未見魏軍，馳書報黃羅漢曰：「吾至石梵，境上帖然，前言皆兒戲耳。", literal: "Wang Chen reached Shifan, saw no Wei army, and sent a swift letter to Huang Luohan: \"I reached Shifan; the border is perfectly calm—the earlier words were all child's play.", idiomatic: "Wang Chen reached Shifan, saw no Wei army, and sent a swift letter to Huang Luohan: \"I reached Shifan; the border is perfectly calm—the earlier words were all child's play." },
  { zh: "」帝聞而疑之。", literal: "\" The emperor heard and grew doubtful.", idiomatic: "\" The emperor heard and grew doubtful." },
  { zh: "庚午，復講，百官戎服以聽。", literal: "On gengwu, he lectured again; the hundred officials listened in military dress.", idiomatic: "On gengwu, he lectured again; the hundred officials listened in military dress." },
  { zh: "辛未，帝使主書李膺至建康，征王僧辯為大都督、荊州刺史，命陳霸先徙鎮揚州。", literal: "On xinwei, the emperor sent Chief Clerk Li Ying to Jiankang to summon Wang Senbian as Grand Commander and Inspector of Jingzhou, and ordered Chen Baxian to transfer and garrison Yangzhou.", idiomatic: "On xinwei, the emperor sent chief clerk Li Ying to Jiankang to summon Wang Senbian as grand commander and inspector of Jingzhou, and ordered Chen Baxian to transfer and garrison Yangzhou." },
  { zh: "僧辯遣豫州刺史侯瑱帥程靈洗等為前軍，兗州刺史杜僧明帥吳明徹等為後軍。", literal: "Senbian sent Yuzhou Inspector Hou Chen to lead Cheng Lingxi and others as vanguard, and Yanzhou Inspector Du Sengming to lead Wu Mingche and others as rearguard.", idiomatic: "Senbian sent Yuzhou inspector Hou Chen to lead Cheng Lingxi and others as vanguard, and Yanzhou inspector Du Sengming to lead Wu Mingche and others as rearguard." },
  { zh: "甲戌，帝夜登鳳皇閣，徙倚歎息曰：「客星入翼、軫、今必敗矣！", literal: "On jiaxu, at night the emperor ascended Phoenix Tower, paced and sighed, and said, \"The guest star has entered Wings and Chariot—now defeat is certain!", idiomatic: "On jiaxu, at night the emperor ascended Phoenix Tower, paced and sighed, and said, \"The guest star has entered Wings and Chariot—now defeat is certain!" },
  { zh: "」嬪御皆泣。", literal: "\" The palace women all wept.", idiomatic: "\" The palace women all wept." },
  { zh: "陸法和聞魏師至，自郢州入漢口，將赴江陵。", literal: "Lu Fahe, hearing Wei troops had arrived, entered the Han mouth from Yingzhou and was about to go to Jiangling.", idiomatic: "Lu Fahe, hearing Wei troops had arrived, entered the Han mouth from Yingzhou and was about to go to Jiangling." },
  { zh: "帝使逆之曰：「此自能破賊，但鎮郢州，不須動也！", literal: "The emperor sent to turn him back, saying, \"This one can break the rebels himself—only garrison Yingzhou; you need not move!", idiomatic: "The emperor sent to turn him back, saying, \"I can break the rebels myself—only garrison Yingzhou; you need not move!" },
  { zh: "」法和還州，堊其城門，著衰絰，坐葦席，終日，乃脫之。", literal: "\" Fahe returned to his province, whitewashed his city gates, put on hemp mourning, sat on a reed mat all day, and only then removed them.", idiomatic: "\" Fahe returned to his province, whitewashed his city gates, put on hemp mourning, sat on a reed mat all day, and only then removed them." },
  { zh: "十一月，帝大閱於津陽門外，遇北風暴雨，輕輦還宮。", literal: "In the eleventh month, the emperor held a great review outside Jinyang Gate; he met north wind and violent rain and returned to the palace in a light carriage.", idiomatic: "In the eleventh month, the emperor held a great review outside Jinyang Gate; he met north wind and violent rain and returned to the palace in a light carriage." },
  { zh: "癸未，魏軍濟漢，於謹令宇文護、楊忠帥精騎先據江津，斷東路。", literal: "On guiwei, Wei armies crossed the Han; Yu Jin ordered Yuwen Hu and Yang Zhong to lead picked cavalry first to seize the river crossing and cut the eastern road.", idiomatic: "On guiwei, Wei armies crossed the Han; Yu Jin ordered Yuwen Hu and Yang Zhong to lead picked cavalry first to seize the river crossing and cut the eastern road." },
  { zh: "甲申，護克武寧，執宗均。", literal: "On jiashen, Hu took Wuning and seized Zong Jun.", idiomatic: "On jiashen, Hu took Wuning and seized Zong Jun." },
  { zh: "是日，帝乘馬出城行柵，插木為之，周圍六十餘里。", literal: "That day the emperor rode out of the city to trace palisades, setting in posts of wood; the circuit was more than sixty li.", idiomatic: "That day the emperor rode out of the city to trace palisades, setting in posts of wood; the circuit was more than sixty li." },
  { zh: "以領軍將軍胡僧祐都督城東諸軍事，尚書右僕射張綰為之副，左僕射王褒都督城西諸軍事，四廂領直元景亮為之副；", literal: "He made Commander of the Guards General Hu Sengyou overseer of all military affairs east of the city, with Right Vice Director of the Secretariat Zhang Wan as his deputy; Left Vice Director Wang Bao overseer west of the city, with Four-Wing Commander of the Palace Guard Yuan Jingliang as his deputy.", idiomatic: "He made commander of the guards Hu Sengyou overseer of all military affairs east of the city, with right vice director of the secretariat Zhang Wan as his deputy; left vice director Wang Bao overseer west of the city, with four-wing commander of the palace guard Yuan Jingliang as his deputy;" },
  { zh: "王公已下各有所守。", literal: "princes and officials downward each had their posts.", idiomatic: "princes and officials downward each had their posts." },
  { zh: "丙戌，命太子巡行城樓，令居人助運木石。", literal: "On bingxu, he ordered the heir apparent to tour the city towers and commanded residents to help transport wood and stone.", idiomatic: "On bingxu, he ordered the heir apparent to tour the city towers and commanded residents to help transport wood and stone." },
  { zh: "夜，魏軍至黃華，去江陵四十里，丁亥，至柵下。", literal: "At night Wei armies reached Huanghua, forty li from Jiangling; on dinghai, they reached below the palisades.", idiomatic: "At night Wei armies reached Huanghua, forty li from Jiangling; on dinghai, they reached below the palisades." },
  { zh: "戊子，巂州刺史裴畿、畿弟新興太守機、武昌太守朱買臣、衡陽太守謝答仁開枇杷門出戰，裴機殺魏儀同三司胡文伐。", literal: "On wuzi, Xizhou Inspector Pei Ji, Ji's younger brother Xinxing Administrator Ji, Wuchang Administrator Zhu Maichen, and Hengyang Administrator Xie Daren opened Pipa Gate and sortied; Pei Ji killed Wei Palace Attendant of the Third Rank Hu Wenfa.", idiomatic: "On wuzi, Xizhou inspector Pei Ji, Ji's younger brother Xinxing administrator Ji, Wuchang administrator Zhu Maichen, and Hengyang administrator Xie Daren opened Pipa Gate and sortied; Pei Ji killed Western Wei palace attendant of the third rank Hu Wenfa." },
  { zh: "畿，之高之子也。", literal: "Ji was Gaozhi's son.", idiomatic: "Ji was Pei Gaozhi's son." },
  { zh: "帝征廣州刺史王琳為湘州刺史，使引兵入援。", literal: "The emperor summoned Guangzhou Inspector Wang Lin as Inspector of Xiangzhou and had him lead troops to reinforce.", idiomatic: "The emperor summoned Guangzhou inspector Wang Lin as inspector of Xiangzhou and had him lead troops to reinforce." },
  { zh: "丁酉，柵內火，焚數千家及城樓二十五，帝臨所焚樓，望魏軍濟江，四顧歎息。", literal: "On dingyou, fire broke out within the palisades, burning several thousand households and twenty-five towers; the emperor came to the burned tower, looked at Wei armies crossing the river, and sighed on every side.", idiomatic: "On dingyou, fire broke out within the palisades, burning several thousand households and twenty-five towers; the emperor came to the burned tower, looked at Wei armies crossing the river, and sighed on every side." },
  { zh: "是夜，遂止宮外，宿民家。", literal: "That night he then stopped outside the palace and lodged in a commoner's house.", idiomatic: "That night he then stopped outside the palace and lodged in a commoner's house." },
  { zh: "己亥，稱居示氐洹寺。", literal: "On jihai, he styled his residence Shizhi Huan Temple.", idiomatic: "On jihai, he styled his residence Shizhi Huan Temple." },
  { zh: "於謹令築長圍，中外信命始絕。", literal: "Yu Jin ordered a long encirclement built; communications inside and outside were cut off from the start.", idiomatic: "Yu Jin ordered a long encirclement built; communications inside and outside were cut off from the start." },
  { zh: "庚子，信州刺史徐世譜、晉安王司馬任約等築壘於馬頭，遙為聲援。", literal: "On gengzi, Xinzhou Inspector Xu Shixie, Jin'an Prince's Chief Administrator Ren Yue, and others built forts at Matou as distant support.", idiomatic: "On gengzi, Xinzhou inspector Xu Shixie, Jin'an prince's chief administrator Ren Yue, and others built forts at Matou as distant support." },
  { zh: "是夜，帝巡城，猶口占為詩，群臣亦有和者。", literal: "That night the emperor toured the walls, still improvising verse; ministers also had matching poems.", idiomatic: "That night the emperor toured the walls, still improvising verse; ministers also had matching poems." },
  { zh: "帝裂帛為書，趣王僧辯曰：「吾忍死待公，可以至矣！", literal: "The emperor tore silk for a letter and urged Wang Senbian: \"I endure death waiting for you—you can arrive now!", idiomatic: "The emperor tore silk for a letter and urged Wang Senbian: \"I endure death waiting for you—you can arrive now!" },
  { zh: "」壬寅，還宮；", literal: "\" On renyin, he returned to the palace.", idiomatic: "\" On renyin, he returned to the palace;" },
  { zh: "癸卯，出長沙寺。", literal: "On guimao, he went out to Changsha Temple.", idiomatic: "On guimao, he went out to Changsha Temple." },
  { zh: "戊申，王褒、胡僧祐、朱買臣、謝答仁等開門出戰，皆敗還。", literal: "On wushen, Wang Bao, Hu Sengyou, Zhu Maichen, Xie Daren, and others opened the gates and sortied; all were defeated and returned.", idiomatic: "On wushen, Wang Bao, Hu Sengyou, Zhu Maichen, Xie Daren, and others opened the gates and sortied; all were defeated and returned." },
  { zh: "己酉，帝移居天居寺；", literal: "On jiyou, the emperor moved to Tianju Temple.", idiomatic: "On jiyou, the emperor moved to Tianju Temple;" },
  { zh: "癸丑，移居長沙寺。", literal: "On guichou, he moved to Changsha Temple.", idiomatic: "On guichou, he moved to Changsha Temple." },
  { zh: "朱買臣按劍進曰：「唯斬宗懍、黃羅漢，可以謝天下！", literal: "Zhu Maichen advanced with sword drawn and said, \"Only beheading Zong Lin and Huang Luohan can answer to the realm!", idiomatic: "Zhu Maichen advanced with sword drawn and said, \"Only beheading Zong Lin and Huang Luohan can answer to the realm!" },
  { zh: "」帝曰：「曩實吾意，宗、黃何罪！", literal: "\" The emperor said, \"Earlier it was indeed my intent—what crime have Zong and Huang!", idiomatic: "\" The emperor said, \"Earlier it was indeed my intent—what crime have Zong and Huang!" },
  { zh: "」二人退入眾中。", literal: "\" The two withdrew into the crowd.", idiomatic: "\" The two withdrew into the crowd." },
  { zh: "王琳軍至長沙，鎮南府長史裴政請間道先報江陵，至百里洲，為魏人所獲。", literal: "Wang Lin's army reached Changsha; Chief Administrator Pei Zheng of the Pacify-the-South Headquarters asked to take a bypath first to report Jiangling; reaching Baili Isle, he was captured by Wei men.", idiomatic: "Wang Lin's army reached Changsha; chief administrator Pei Zheng of the Pacify-the-South headquarters asked to take a bypath first to report Jiangling; reaching Baili Isle, he was captured by Wei men." },
  { zh: "梁王察謂政曰：「我，武皇帝之孫也，不可為爾君乎？", literal: "Prince Cha of Liang told Zheng, \"I am the Martial Emperor's grandson—can I not be your lord?", idiomatic: "Prince Xiao Cha of Liang told Zheng, \"I am the Martial Emperor's grandson—can I not be your lord?" },
  { zh: "若從我計，貴及子孫；", literal: "If you follow my plan, honor will reach your sons and grandsons.", idiomatic: "If you follow my plan, honor will reach your sons and grandsons;" },
  { zh: "如或不然，腰領分矣。", literal: "If not, waist and neck will be parted.", idiomatic: "if not, waist and neck will be parted." },
  { zh: "」政詭對曰：「唯命。", literal: "\" Zheng answered deceitfully, \"Only command.", idiomatic: "\" Zheng answered deceitfully, \"Only command." },
  { zh: "」察鎖之至城下，使言曰：「王僧辯聞台城被圍，已自為帝。", literal: "\" Cha locked him and brought him below the walls, making him say, \"Wang Senbian, hearing the capital is besieged, has already made himself emperor.", idiomatic: "\" Cha locked him and brought him below the walls, making him say, \"Wang Senbian, hearing the capital is besieged, has already made himself emperor." },
  { zh: "王琳孤弱，不復能來。", literal: "Wang Lin is isolated and weak and can come no more.", idiomatic: "Wang Lin is isolated and weak and can come no more." },
  { zh: "」政告城中曰：「援兵大至，各思自勉。", literal: "\" Zheng told the city, \"Relief armies are coming in force—each of you think how to exert yourselves.", idiomatic: "\" Zheng told the city, \"Relief armies are coming in force—each of you think how to exert yourselves." },
  { zh: "吾以間使被擒，當碎身報國。", literal: "I was captured as a secret envoy and must shatter my body to repay the state.", idiomatic: "I was captured as a secret envoy and must shatter my body to repay the state." },
  { zh: "」監者擊其口，察怒，命速殺之。", literal: "\" The guard struck his mouth; Cha was angry and ordered him killed at once.", idiomatic: "\" The guard struck his mouth; Cha was angry and ordered him killed at once." },
  { zh: "西中郎參軍蔡大業諫曰：「此民望也，殺之，則荊州不可下矣。", literal: "Western Central Commander's Aide Cai Daye remonstrated, \"This man is the people's hope—kill him and Jingzhou cannot be taken.", idiomatic: "Western central commander's aide Cai Daye remonstrated, \"This man is the people's hope—kill him and Jingzhou cannot be taken." },
  { zh: "」乃釋之。", literal: "\" He was then released.", idiomatic: "\" He was then released." },
  { zh: "政，之禮之子；", literal: "Zheng was Zhili's son.", idiomatic: "Zheng was Pei Zhili's son." },
  { zh: "大業，大寶之弟也。", literal: "Daye was Dabao's younger brother.", idiomatic: "Daye was Cai Dabao's younger brother." },
  { zh: "時徵兵四方，皆未至。", literal: "At that time troops summoned from the four quarters had not yet arrived.", idiomatic: "At that time troops summoned from the four quarters had not yet arrived." },
  { zh: "甲寅，魏人百道攻城，城中負戶蒙楯，胡僧祐親當矢石，盡夜督戰，獎勵將士，明行賞罰，眾鹹致死，所向摧殄，魏不得前。", literal: "On jiayin, Wei men attacked the city on a hundred roads; within the city men bore doors as shields; Hu Sengyou personally met arrows and stones, supervised fighting all night, rewarded officers and men, clearly applied rewards and punishments—the masses all died where they stood, crushed all they met, and Wei could not advance.", idiomatic: "On jiayin, Wei men attacked the city on a hundred roads; within the city men bore doors as shields; Hu Sengyou personally met arrows and stones, supervised fighting all night, rewarded officers and men, clearly applied rewards and punishments—the masses all died where they stood, crushed all they met, and Wei could not advance." },
  { zh: "俄而僧祐中流矢死，內外大駭。", literal: "Soon Sengyou was struck by a flying arrow and died; inside and outside were greatly alarmed.", idiomatic: "Soon Sengyou was struck by a flying arrow and died; inside and outside were greatly alarmed." },
  { zh: "魏悉眾攻柵，反者開西門納魏師，帝與太子、王褒、謝答仁、朱買臣退保金城，令汝南王大封、晉熙王大圓質于于謹以請和。", literal: "Wei mustered all forces to attack the palisades; defectors opened the west gate and admitted Wei troops; the emperor with the heir apparent, Wang Bao, Xie Daren, and Zhu Maichen withdrew to hold Golden City and sent Prince Feng of Runan and Prince Yuan of Jinxi as hostages to Yu Jin to sue for peace.", idiomatic: "Wei mustered all forces to attack the palisades; defectors opened the west gate and admitted Wei troops; the emperor with the heir apparent, Wang Bao, Xie Daren, and Zhu Maichen withdrew to hold Golden City and sent Prince Feng of Runan and Prince Yuan of Jinxi as hostages to Yu Jin to sue for peace." },
  { zh: "魏軍之初至也，眾以王僧辯子侍中顗可為都督，帝不用，更奪其兵，使與左右十人入守殿中；", literal: "When Wei armies first arrived, the masses thought Wang Senbian's son, Attendant-in-Ordinary Yan, could be commander; the emperor did not use him, further stripped his troops, and had him with ten attendants enter to guard the palace hall.", idiomatic: "When Wei armies first arrived, the masses thought Wang Senbian's son, attendant-in-ordinary Yan, could be commander; the emperor did not use him, further stripped his troops, and had him with ten attendants enter to guard the palace hall;" },
  { zh: "及胡僧祐死，乃用為都督城諸軍事。", literal: "when Hu Sengyou died, he was then used as commander of all military affairs of the city.", idiomatic: "when Hu Sengyou died, he was then used as commander of all military affairs of the city." },
  { zh: "裴畿、裴機、歷陽侯峻皆出降。", literal: "Pei Ji, Pei Ji, and Marquis Jun of Liyang all came out and surrendered.", idiomatic: "Pei Ji, Pei Ji, and Marquis Jun of Liyang all came out and surrendered." },
  { zh: "於謹以機手殺胡文伐，並畿殺之。", literal: "Yu Jin, because Ji had killed Hu Wenfa with his own hand, killed Ji together with Ji.", idiomatic: "Yu Jin, because Ji had killed Hu Wenfa with his own hand, killed both Ji brothers." },
  { zh: "峻，淵猷之子也。", literal: "Jun was Yuanyou's son.", idiomatic: "Jun was Xiao Yuanyou's son." },
  { zh: "時城南雖破，而城北諸將猶苦戰。", literal: "At that time though the south of the city was broken, the generals north of the city still fought bitterly.", idiomatic: "At that time though the south of the city was broken, the generals north of the city still fought bitterly." },
  { zh: "日暝，聞城陷，乃散。", literal: "At dusk they heard the city had fallen and then dispersed.", idiomatic: "At dusk they heard the city had fallen and then dispersed." },
  { zh: "帝入東閣竹殿，命舍人高善寶焚古今圖書十四萬卷，將自赴火，宮人左右共止之。", literal: "The emperor entered the bamboo hall of the eastern wing, ordered Palace Attendant Gao Shanbao to burn 140,000 volumes of ancient and modern books and maps, and was about to throw himself into the fire; palace attendants left and right together stopped him.", idiomatic: "The emperor entered the bamboo hall of the eastern wing, ordered palace attendant Gao Shanbao to burn 140,000 volumes of ancient and modern books and maps, and was about to throw himself into the fire; palace attendants left and right together stopped him." },
  { zh: "又以寶劍斫柱令折，歎曰：「文武之道，今夜盡矣！", literal: "He also took a precious sword and hacked a pillar until it broke, sighing, \"The way of wen and wu ends tonight!", idiomatic: "He also took a precious sword and hacked a pillar until it broke, sighing, \"The way of wen and wu ends tonight!" },
  { zh: "」乃使御史中丞王孝祀作降文。", literal: "\" He then had Censor-in-Chief Wang Xiaosi compose the surrender document.", idiomatic: "\" He then had censor-in-chief Wang Xiaosi compose the surrender document." },
  { zh: "謝答仁、朱買臣諫曰：「城中兵眾猶強，乘暗突圍而出，賊必驚，因而薄之，可渡江就任約。", literal: "Xie Daren and Zhu Maichen remonstrated, \"Soldiers in the city are still strong; ride the dark and burst through the encirclement—the rebels will be startled; press them and you can cross the river to join Ren Yue.", idiomatic: "Xie Daren and Zhu Maichen remonstrated, \"Soldiers in the city are still strong; ride the dark and burst through the encirclement—the rebels will be startled; press them and you can cross the river to join Ren Yue." },
  { zh: "」帝素不便走馬，曰：「事必無成，只增辱耳！", literal: "\" The emperor had never been skilled at riding and said, \"The affair cannot succeed—it only adds disgrace!", idiomatic: "\" The emperor had never been skilled at riding and said, \"The affair cannot succeed—it only adds disgrace!" },
  { zh: "」答仁求自扶，帝以問王褒，褒曰：「答仁，侯景之黨，豈足可信！", literal: "\" Daren asked to support him himself; the emperor questioned Wang Bao; Bao said, \"Daren was Hou Jing's follower—how can he be trusted!", idiomatic: "\" Daren asked to support him himself; the emperor questioned Wang Bao; Bao said, \"Daren was Hou Jing's follower—how can he be trusted!" },
  { zh: "成彼之勳，不如降也。", literal: "To complete his merit is not as good as surrender.", idiomatic: "To complete his merit is not as good as surrender." },
  { zh: "」答仁又請守子城，收兵可得五千人，帝然之，即授城中大都督，配以公主。", literal: "\" Daren again asked to hold the inner citadel and gather troops—five thousand men could be had; the emperor agreed, at once made him grand commander within the city, and paired him with a princess.", idiomatic: "\" Daren again asked to hold the inner citadel and gather troops—five thousand men could be had; the emperor agreed, at once made him grand commander within the city, and paired him with a princess." },
  { zh: "既而召王褒謀之，以為不可。", literal: "Soon he summoned Wang Bao to plan; Bao thought it impossible.", idiomatic: "Soon he summoned Wang Bao to plan; Bao thought it impossible." },
  { zh: "答仁請入不得，歐血而去。", literal: "Daren asked to enter and could not; he spat blood and left.", idiomatic: "Daren asked to enter and could not; he spat blood and left." },
  { zh: "於謹征太子為質，帝使王褒送之。", literal: "Yu Jin demanded the heir apparent as hostage; the emperor had Wang Bao escort him.", idiomatic: "Yu Jin demanded the heir apparent as hostage; the emperor had Wang Bao escort him." },
  { zh: "謹子以褒善書，給之紙筆，褒乃書曰：「柱國常山公家奴王褒。", literal: "Jin's son, because Bao wrote well, gave him paper and brush; Bao then wrote, \"House slave Wang Bao of pillar-of-state Duke Jin of Changshan.", idiomatic: "Jin's son, because Bao wrote well, gave him paper and brush; Bao then wrote, \"House slave Wang Bao of pillar-of-state Duke Jin of Changshan." },
  { zh: "」有頃，黃門郎裴政犯門而出。", literal: "\" After a while, Yellow Gate Gentleman Pei Zheng broke through the gate and came out.", idiomatic: "\" After a while, yellow gate gentleman Pei Zheng broke through the gate and came out." },
  { zh: "帝遂去羽儀文物，白馬素衣出東門，抽劍擊闔曰：「蕭世誠一至此乎！", literal: "The emperor then removed feather banners and ritual objects, rode a white horse in plain clothes out the east gate, drew his sword and struck the gate bar, saying, \"Has Xiao Shicheng come to this!", idiomatic: "The emperor then removed feather banners and ritual objects, rode a white horse in plain clothes out the east gate, drew his sword and struck the gate bar, saying, \"Has Xiao Shicheng come to this!" },
  { zh: "」魏軍士度塹牽其轡，至白馬寺北，奪其所乘駿馬，以駑馬代之，遣長壯胡人手扼其背以行，逢於謹，胡人牽帝使拜。", literal: "\" Wei soldiers crossed the moat and took his reins; north of White Horse Temple they seized his fine horse and replaced it with a nag, sent tall strong barbarian men to grip his back as he walked, met Yu Jin, and the barbarians pulled the emperor to make him bow.", idiomatic: "\" Wei soldiers crossed the moat and took his reins; north of White Horse Temple they seized his fine horse and replaced it with a nag, sent tall strong barbarian men to grip his back as he walked, met Yu Jin, and the barbarians pulled the emperor to make him bow." },
  { zh: "梁王察使鐵騎擁帝入營，囚於烏幔之下，甚為察所詰辱。", literal: "Prince Cha of Liang sent iron cavalry to crowd the emperor into camp and imprisoned him beneath black felt, greatly reviled by Cha.", idiomatic: "Prince Xiao Cha sent iron cavalry to crowd the emperor into camp and imprisoned him beneath black felt, greatly reviled by Cha." },
  { zh: "乙卯，於謹令開府儀同三司長孫儉入據金城。", literal: "On yimao, Yu Jin ordered Palace Gate Commander of the First Rank Zhangsun Jian to enter and hold Golden City.", idiomatic: "On yimao, Yu Jin ordered palace gate commander of the first rank Zhangsun Jian to enter and hold Golden City." },
  { zh: "帝紿儉云：「城中埋金千斤，欲以相贈。", literal: "The emperor deceived Jian, saying, \"A thousand jin of gold are buried in the city—I wish to give them to you.", idiomatic: "The emperor deceived Jian, saying, \"A thousand jin of gold are buried in the city—I wish to give them to you." },
  { zh: "」儉乃將帝入城。", literal: "\" Jian then led the emperor into the city.", idiomatic: "\" Jian then led the emperor into the city." },
  { zh: "帝因述察見辱之狀，謂儉曰：「向聊相紿，欲言此耳，豈有天子自埋金乎！", literal: "The emperor then described how he had been insulted when he saw Cha and told Jian, \"Just now I briefly deceived you—I wanted to say this; would a Son of Heaven bury gold himself!", idiomatic: "The emperor then described how he had been insulted when he saw Cha and told Jian, \"Just now I briefly deceived you—I wanted to say this; would a Son of Heaven bury gold himself!" },
  { zh: "」儉乃留帝於主衣庫。", literal: "\" Jian then detained the emperor in the wardrobe storehouse.", idiomatic: "\" Jian then detained the emperor in the wardrobe storehouse." },
  { zh: "帝性殘忍，且懲高祖寬縱之弊，故為政尚嚴。", literal: "The emperor was by nature cruel, and because he punished the laxness of High Ancestor, his government favored severity.", idiomatic: "The emperor was by nature cruel, and because he punished the laxness of High Ancestor, his government favored severity." },
  { zh: "及魏師圍城，獄中死囚且數千人，有司請釋之以充戰士；", literal: "When Wei troops besieged the city, condemned prisoners in the jails numbered nearly several thousand; the authorities asked to release them to fill out the fighting ranks.", idiomatic: "When Wei troops besieged the city, condemned prisoners in the jails numbered nearly several thousand; the authorities asked to release them to fill out the fighting ranks;" },
  { zh: "帝不許，悉令棓殺之，事未成而城陷。", literal: "the emperor would not consent and ordered them all clubbed to death; the affair was not finished when the city fell.", idiomatic: "the emperor would not consent and ordered them all clubbed to death; the affair was not finished when the city fell." },
  { zh: "中書郎殷不害先於別所督戰，城陷，失其母。", literal: "Secretariat Cadet Yin Buhai had earlier supervised fighting at another post; when the city fell, he lost his mother.", idiomatic: "Secretariat cadet Yin Buhai had earlier supervised fighting at another post; when the city fell, he lost his mother." },
  { zh: "時冰雪交積，凍死者填滿溝塹。", literal: "At that time ice and snow piled together; the frozen dead filled ditches and ravines.", idiomatic: "At that time ice and snow piled together; the frozen dead filled ditches and ravines." },
  { zh: "不害行哭於道，求其母屍，無所不至。", literal: "Buhai walked weeping in the roads, seeking his mother's corpse, going everywhere.", idiomatic: "Buhai walked weeping in the roads, seeking his mother's corpse, going everywhere." },
  { zh: "見溝中死人，輒投下捧視，舉體凍濕，水漿不入口，號哭不輟聲。", literal: "Seeing dead in the ditches, he would leap down, lift and look; his whole body frozen and wet, he took no water or gruel, and his wailing never ceased.", idiomatic: "Seeing dead in the ditches, he would leap down, lift and look; his whole body frozen and wet, he took no water or gruel, and his wailing never ceased." },
  { zh: "如是七日，乃得之。", literal: "After seven days thus, he found her.", idiomatic: "After seven days thus, he found her." },
  { zh: "十二月，丙辰，徐世譜、任約退戍巴陵。", literal: "In the twelfth month, on bingchen, Xu Shixie and Ren Yue withdrew to garrison Baling.", idiomatic: "In the twelfth month, on bingchen, Xu Shixie and Ren Yue withdrew to garrison Baling." },
  { zh: "於謹逼帝使為書召王僧辯，帝不可。", literal: "Yu Jin compelled the emperor to write summoning Wang Senbian; the emperor would not.", idiomatic: "Yu Jin compelled the emperor to write summoning Wang Senbian; the emperor would not." },
  { zh: "使者曰：「王今豈得自由？", literal: "The envoy said, \"Does Your Majesty now have freedom?", idiomatic: "The envoy said, \"Does Your Majesty now have freedom?" },
  { zh: "」帝曰：「我既不自由，僧辯亦不由我。", literal: "\" The emperor said, \"Since I am not free, Senbian is not subject to me either.", idiomatic: "\" The emperor said, \"Since I am not free, Senbian is not subject to me either." },
  { zh: "」又從長孫儉求宮人王氏、苟氏及幼子犀首，儉並還之。", literal: "\" He also asked Zhangsun Jian for palace women Lady Wang and Lady Gou and his young son Xishou; Jian returned them all.", idiomatic: "\" He also asked Zhangsun Jian for palace women Lady Wang and Lady Gou and his young son Xishou; Jian returned them all." },
  { zh: "或問：「何意焚書？", literal: "Someone asked, \"What was the intent in burning the books?", idiomatic: "Someone asked, \"What was the intent in burning the books?" },
  { zh: "」帝曰：「讀書萬卷，猶有今日，故焚之！", literal: "\" The emperor said, \"I read ten thousand volumes and still had this day—therefore I burned them!", idiomatic: "\" The emperor said, \"I read ten thousand volumes and still had this day—therefore I burned them!" },
  { zh: "庚申，齊主北巡，至達速嶺，行視山川險要，將起長城。", literal: "On gengshen, the Qi ruler toured north, reached Dasu Ridge, went viewing mountains and rivers for strategic points, and intended to raise the Long Wall.", idiomatic: "On gengshen, the Qi ruler toured north, reached Dasu Ridge, went viewing mountains and rivers for strategic points, and intended to raise the Long Wall." },
  { zh: "辛未，帝為魏人所殺。", literal: "On xinwei, the emperor was killed by Wei men.", idiomatic: "On xinwei, the emperor was killed by Wei men." },
  { zh: "梁王察遣尚書傅准監刑，以土囊隕之。", literal: "Prince Cha of Liang sent Secretary Fu Zhun to oversee the execution; they crushed him with a bag of earth.", idiomatic: "Prince Xiao Cha sent secretary Fu Zhun to oversee the execution; they crushed him with a bag of earth." },
  { zh: "察使以布帕纏屍，斂以蒲席，束以白茅，葬於津陽門外。", literal: "Cha had the corpse wrapped in cloth, enshrouded in a rush mat, bound with white thatch, and buried outside Jinyang Gate.", idiomatic: "Cha had the corpse wrapped in cloth, enshrouded in a rush mat, bound with white thatch, and buried outside Jinyang Gate." },
  { zh: "並殺愍懷太子元良、始安王方略、桂陽王大成等。", literal: "He also killed the Minhuai heir apparent Yuanliang, Prince Fanglue of Shi'an, Prince Dacheng of Guiyang, and others.", idiomatic: "He also killed the Minhuai heir apparent Yuanliang, Prince Fanglue of Shi'an, Prince Dacheng of Guiyang, and others." },
  { zh: "世祖性好書，常令左右讀書，晝夜不絕，雖熟睡，卷猶不釋，或差誤及欺之，帝輒驚寤。", literal: "Shizu loved books, constantly had attendants read aloud day and night without cease; even in deep sleep the scroll was not released; if there was error or deception, the emperor would start awake.", idiomatic: "Shizu loved books, constantly had attendants read aloud day and night without cease; even in deep sleep the scroll was not released; if there was error or deception, the emperor would start awake." },
  { zh: "作文章，援筆立就。", literal: "Composing essays, he took up the brush and finished at once.", idiomatic: "Composing essays, he took up the brush and finished at once." },
  { zh: "常言：「我韜於文士，愧於武夫。", literal: "He often said, \"I am concealed among literary men and ashamed before martial men.", idiomatic: "He often said, \"I am concealed among literary men and ashamed before martial men." },
  { zh: "」論者以為得言。", literal: "\" Critics held that he spoke to the point.", idiomatic: "\" Critics held that he spoke to the point." },
  { zh: "魏立梁王察為梁主，資以荊州之地，延袤三百里，仍取其雍州之地。", literal: "Wei enthroned Prince Cha of Liang as Liang ruler, endowed him with Jingzhou territory three hundred li in extent, and also took Yongzhou territory for him.", idiomatic: "Western Wei enthroned Prince Xiao Cha as Liang ruler, endowed him with Jingzhou territory three hundred li in extent, and also took Yongzhou territory for him." },
  { zh: "察居江陵東城，魏置防主，將兵居西城，名曰助防，外示助察備御，內實防之。", literal: "Cha dwelt in Jiangling's eastern city; Wei set a defense chief and garrisoned troops in the western city, called Aid Defense—outwardly showing aid to Cha for defense, inwardly in fact guarding against him.", idiomatic: "Cha dwelt in Jiangling's eastern city; Western Wei set a defense chief and garrisoned troops in the western city, called Aid Defense—outwardly showing aid to Cha for defense, inwardly in fact guarding against him." },
  { zh: "以前儀同三司王悅留鎮江陵。", literal: "Former Palace Attendant of the Third Rank Wang Yue was left to garrison Jiangling.", idiomatic: "Former palace attendant of the third rank Wang Yue was left to garrison Jiangling." },
  { zh: "於謹收府庫珍寶及宋渾天儀、梁銅晷表、大玉徑四尺及諸法物；", literal: "Yu Jin collected treasury treasures and the Song armillary sphere, Liang bronze sundial, great jade four feet across, and various ritual objects.", idiomatic: "Yu Jin collected treasury treasures and the Song armillary sphere, Liang bronze sundial, great jade four feet across, and various ritual objects;" },
  { zh: "盡俘王公以下及選百姓男女數萬口為奴婢，分賞三軍，驅歸長安，小弱者皆殺之。", literal: "he took captive princes and officials downward and selected common men and women, tens of thousands as slaves and maidservants, distributed them as rewards to the three armies, drove them back to Chang'an, and killed all the small and weak.", idiomatic: "he took captive princes and officials downward and selected common men and women, tens of thousands as slaves and maidservants, distributed them as rewards to the three armies, drove them back to Chang'an, and killed all the small and weak." },
  { zh: "得免者三百餘家，而人馬所踐及凍死者什二三。", literal: "Those who escaped numbered more than three hundred households; of men and horses trampled and frozen to death, two or three in ten.", idiomatic: "Those who escaped numbered more than three hundred households; of men and horses trampled and frozen to death, two or three in ten." },
  { zh: "魏師之在江陵也，梁王察將尹德毅說察曰：「魏虜貪惏，肆其殘忍，殺掠士民，不可勝紀。", literal: "While Wei troops were at Jiangling, Liang Prince Cha's general Yin Deyi urged Cha, \"Wei barbarians are greedy and cruel, indulging their savagery, killing and plundering gentlemen and people beyond counting.", idiomatic: "While Wei troops were at Jiangling, Liang prince Xiao Cha's general Yin Deyi urged Cha, \"Wei barbarians are greedy and cruel, indulging their savagery, killing and plundering gentlemen and people beyond counting." },
  { zh: "江東之人塗炭至此，鹹謂殿下為之。", literal: "The people east of the Yangtze are charred to this point—all say Your Highness did it.", idiomatic: "The people east of the Yangtze are charred to this point—all say Your Highness did it." },
  { zh: "殿下既殺人父兄，孤人子弟，人盡仇也，誰與為國！", literal: "Your Highness has killed men's fathers and elder brothers and orphaned men's sons and younger brothers—every man is an enemy; who will make a state with you!", idiomatic: "Your Highness has killed men's fathers and elder brothers and orphaned men's sons and younger brothers—every man is an enemy; who will make a state with you!" },
  { zh: "今魏之精銳盡萃於此，若殿下為設享會，請於謹等為歡，預伏武士，因而斃之，分命諸將，掩其營壘，大殲群丑，俾無遺類。", literal: "Now Wei's picked troops are all gathered here; if Your Highness sets a feast and invites Yu Jin and the rest to rejoice, with armed men hidden beforehand to kill them thereby, then assign the various generals to strike their camps and greatly annihilate the whole pack so none remain.", idiomatic: "Now Wei's picked troops are all gathered here; if Your Highness sets a feast and invites Yu Jin and the rest to rejoice, with armed men hidden beforehand to kill them thereby, then assign the various generals to strike their camps and greatly annihilate the whole pack so none remain." },
  { zh: "收江陵百姓，撫而安之，文武群寮，隨材銓授。", literal: "Take in Jiangling's people, comfort and settle them, civil and military officials—all appoint according to talent.", idiomatic: "Take in Jiangling's people, comfort and settle them, civil and military officials—all appoint according to talent." },
  { zh: "魏人懾息，未敢送死，王僧辯之徒，折簡可致。", literal: "Wei men will cower and not dare court death; Wang Senbian and his sort can be summoned with a folded note.", idiomatic: "Wei men will cower and not dare court death; Wang Senbian and his sort can be summoned with a folded note." },
  { zh: "然後朝服濟江，入踐皇極，晷刻之間，大功可立。", literal: "Then in court robes cross the river, enter and tread the supreme pole—in the space between sundial marks, great merit can be established.", idiomatic: "Then in court robes cross the river, enter and tread the supreme pole—in the space between sundial marks, great merit can be established." },
  { zh: "古人云：『天與不取，反受其咎。", literal: "The ancients said, 'Heaven gives and you do not take—you instead receive its blame.", idiomatic: "The ancients said, 'Heaven gives and you do not take—you instead receive its blame." },
  { zh: "』願殿下恢弘遠略，勿懷匹夫之行。", literal: "' I wish Your Highness to enlarge far-reaching design and not harbor the conduct of a common man.", idiomatic: "' I wish Your Highness to enlarge far-reaching design and not harbor the conduct of a common man." },
  { zh: "」察曰：「卿此策非不善也，然魏人待我厚，未可背德。", literal: "\" Cha said, \"Your plan is not ungood, yet Wei men have treated me generously—I cannot betray their virtue.", idiomatic: "\" Cha said, \"Your plan is not ungood, yet Wei men have treated me generously—I cannot betray their virtue." },
  { zh: "若遽為卿計，人將不食吾餘。", literal: "If I hastily followed your plan, men would not eat what remained of me.", idiomatic: "If I hastily followed your plan, men would not eat what remained of me." },
  { zh: "」既擊闔城長幼被虜，又失襄陽，察乃歎曰：「恨不用尹德毅之言！", literal: "\" After striking the gate bar, old and young of the city were taken captive, and Xiangyang was also lost; Cha then sighed, \"I regret not using Yin Deyi's words!", idiomatic: "\" After the city's old and young were taken captive and Xiangyang was also lost, Cha then sighed, \"I regret not using Yin Deyi's words!" },
  { zh: "王僧辯、陳霸先等共奉江州刺史晉安王方智為太宰，承製。", literal: "Wang Senbian, Chen Baxian, and others together upheld Jingzhou Inspector Prince Fangzhi of Jin'an as Grand Preceptor and received his commands.", idiomatic: "Wang Senbian, Chen Baxian, and others together upheld Jingzhou inspector Prince Fangzhi of Jin'an as grand preceptor and received his commands." },
  { zh: "王褒、王克、劉□、宗懍、殷不害及尚書右丞吳興沈炯至長安，太師泰厚禮之。", literal: "Wang Bao, Wang Ke, Liu □, Zong Lin, Yin Buhai, and Right Assistant Director Shen Jiong of Wuxing reached Chang'an; Grand Preceptor Tai treated them with great courtesy.", idiomatic: "Wang Bao, Wang Ke, Liu □, Zong Lin, Yin Buhai, and right assistant director Shen Jiong of Wuxing reached Chang'an; Grand Preceptor Yuwen Tai treated them with great courtesy." },
  { zh: "泰親至於謹第，宴勞極歡，賞謹奴婢千口及梁之寶物並雅樂一部，別封新野公；", literal: "Tai personally came to Jin's residence, feasted and rewarded him with utmost joy, granted Jin a thousand slaves and maidservants and Liang treasures together with a full set of court music, and separately enfeoffed him as Duke of Xinye.", idiomatic: "Yuwen Tai personally came to Yu Jin's residence, feasted and rewarded him with utmost joy, granted Jin a thousand slaves and maidservants and Liang treasures together with a full set of court music, and separately enfeoffed him as Duke of Xinye;" },
  { zh: "謹固辭，不許。", literal: "Jin firmly declined; it was not permitted.", idiomatic: "Jin firmly declined; it was not permitted." },
  { zh: "謹自以久居重任，功名既立，欲保優閒，乃上先所乘駿馬及所著鎧甲等。", literal: "Jin himself, having long held weighty office and his merit already established, wished to preserve ease and leisure, and therefore submitted the fine horses he had formerly ridden and the armor he had worn.", idiomatic: "Jin himself, having long held weighty office and his merit already established, wished to preserve ease and leisure, and therefore submitted the fine horses he had formerly ridden and the armor he had worn." },
  { zh: "泰識其意，曰：「今巨猾未平，公豈得遽爾獨善！", literal: "Tai understood his intent and said, \"Now the great villain is not yet pacified—how can you so hastily seek private ease alone!", idiomatic: "Yuwen Tai understood his intent and said, \"Now the great villain is not yet pacified—how can you so hastily seek private ease alone!" },
  { zh: "」遂不受。", literal: "\" He therefore did not accept them.", idiomatic: "\" He therefore did not accept them." },
  { zh: "是歲，魏秦州刺史章武孝公宇文導卒。", literal: "That year, Wei Qinzhou Inspector Duke Xiao of Zhangwu Yuwen Dao died.", idiomatic: "That year, Western Wei Qinzhou inspector Duke Xiao of Zhangwu Yuwen Dao died." },
  { zh: "魏加益州刺史尉遲迥督六州，通前十八州，自劍閣以南，得承製封拜及黜陟。", literal: "Wei added for Yizhou Inspector Yuchi Tong oversight of six provinces, eighteen provinces in all with those before, and from Jian'ge south he might receive commands to enfeoff and dismiss and promote and demote.", idiomatic: "Western Wei added for Yizhou inspector Yuchi Tong oversight of six provinces, eighteen provinces in all with those before, and from Jian'ge south he might receive commands to enfeoff and dismiss and promote and demote." },
  { zh: "迥明賞罰，布威恩，綏輯新民，經略未附，華、夷懷之。", literal: "Tong made rewards and punishments clear, spread majesty and grace, pacified and gathered new subjects, strategized over those not yet attached—Chinese and barbarians all cherished him.", idiomatic: "Tong made rewards and punishments clear, spread majesty and grace, pacified and gathered new subjects, strategized over those not yet attached—Chinese and barbarians all cherished him." },
  { zh: "category:資治通鑑", literal: "category: Comprehensive Mirror in Aid of Governance", idiomatic: "category: Comprehensive Mirror in Aid of Governance" }
];
